NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'I Chronicles'

CHAPTERS = {
    1: {
        1: 'Adam, Set, Enóš,',
        2: 'Kenán, Mahalalél, Jered,',
        3: 'Henoh, Matuzalem, Lameh,',
        4: 'Noe, Sem, Ham in Jafet.',
        5: 'Jafetovi sinovi: Gomer, Magóg, Madáj, Javán, Tubál, Mešeh in Tirás.',
        6: 'Gomerjevi sinovi: Aškenáz, Rifát in Togarmá.',
        7: '§ Javánovi sinovi: Elišá, Taršíš, Kitéjec in Dodanim.',
        8: 'Hamovi sinovi: Kuš, Micrájim, Put in Kánaan.',
        9: 'Kuševi sinovi: Sebá, Havilá, Sabtá, Ramá in Sabtehá. Ramájeva sinova: Šebá in Dedán.',
        10: 'Kuš je zaplodil Nimróda. Ta je začel postajati mogočen na zemlji.',
        11: 'Micrájim je zaplodil Ludima, Anamima, Lehabima, Nafthima,',
        12: 'Patrusima, Kasluhima (iz katerega so izvirali Filistejci) in Kaftoréjca.',
        13: 'Kánaan je zaplodil svojega prvorojenca Sidóna in Heta,',
        14: 'tudi Jebusejca, Amoréjca, Girgašéjca,',
        15: 'Hivéjca, Arkéjca, Sinéjca,',
        16: 'Arvádejca, Cemaréjca in Hamatéjca.',
        17: 'Semovi sinovi: Elám, Asúr, Arpahšád, Lud, Arám, Uc, Hul, Geter in Mešeh.',
        18: 'Arpahšád je zaplodil Šelá in Šelá je zaplodil Eberja.',
        19: 'Eberju sta bila rojena dva sinova. Ime prvega je bilo Peleg, ker je bila v njegovih dneh zemlja razdeljena. Ime njegovega brata je bilo Joktán.',
        20: 'Joktán je zaplodil Almodáda, Šelefa, Hacarmáveta, Jeraha,',
        21: 'tudi Hadoráma, Uzála, Diklá,',
        22: 'Ebála, Abimaéla, Šebája,',
        23: 'Ofírja, Havilá in Jobába. Vsi ti so bili Joktánovi sinovi.',
        24: 'Sem, Arpahšád, Šelá,',
        25: 'Eber, Peleg, Regu,',
        26: 'Serúg, Nahór, Terah,',
        27: 'Abram; isti je Abraham.',
        28: 'Abrahamovi sinovi: Izak in Izmael.',
        29: 'To so njihovi rodovi: Izmaelov prvorojenec Nebajót, potem Kedár, Adbeél, Mibsám,',
        30: 'Mišmá, Dumá, Masá, Hadád, Temá,',
        31: 'Jetúr, Nafíš in Kedma. To so Izmaelovi sinovi.',
        32: 'Torej sinovi Abrahamove priležnice Ketúre: rodila je Zimrána, Jokšána, Medána, Midjána, Jišbáka in Šuaha. Jokšánova sinova sta: Šebá in Dedán.',
        33: 'Midjánovi sinovi: Efá, Efer, Henoh, Abidá in Eldaá. Vsi ti so Ketúrini sinovi.',
        34: 'Abraham je zaplodil Izaka. Izakova sinova: Ezav in Izrael.',
        35: 'Ezavovi sinovi: Elifáz, Reguél, Jeúš, Jalám in Korah.',
        36: 'Elifázovi sinovi: Temán, Omár, Cefi, Gatám, Kenáz, Timná in Amálek.',
        37: 'Reguélovi sinovi: Nahat, Zerah, Šamá in Mizá.',
        38: 'Seírjevi sinovi: Lotán, Šobál, Cibón, Aná, Dišón, Ecer in Dišán.',
        39: 'Lotánovi sinovi: Horí, Homám; in Timna je bila Lotánova sestra.',
        40: 'Šobálovi sinovi: Alián, Manáhat, Ebál, Šefí, in Onám. Cibónovi sinovi: Ajá in Aná.',
        41: '§ Anájevi sinovi: Dišón. Dišónovi sinovi: Amrám, Ešbán, Jitrán in Kerán.',
        42: 'Ecerjevi sinovi: Bilhán, Zaaván in Jakan. Dišánovi sinovi: Uc in Arán.',
        43: 'Torej ti so kralji, ki so kraljevali v edomski deželi, preden je katerikoli kralj kraljeval nad Izraelovi otroci: Beórjev sin Bela; in ime njegovega mesta je bilo Dinhába.',
        44: 'Ko je bil Bela mrtev, je namesto njega zakraljeval Jobáb, Zerahov sin iz Bocre.',
        45: 'Ko je bil Jobáb mrtev, je namesto njega zakraljeval Hušám, iz dežele Temáncev.',
        46: 'Ko je bil Hušám mrtev, je namesto njega zakraljeval Hadád, Bedádov sin, ki je na moábskem polju udaril Midján, in ime tega mesta je bilo Avít.',
        47: 'Ko je bil Hadád mrtev, je namesto njega zakraljeval Samlá iz Masréke.',
        48: 'Ko je bil Samlá mrtev, je namesto njega zakraljeval Šaúl iz Rehobóta pri reki.',
        49: 'Ko je bil Šaúl mrtev, je namesto njega zakraljeval Ahbórjev sin Báal Hanán.',
        50: 'Ko je bil Báal Hanán mrtev, je namesto njega zakraljeval Hadád, in ime njegovega mesta je bilo Pagú; in ime njegove žene je bilo Mehetabéla, hči Me Zahábove hčere Matréde.',
        51: 'Tudi Hadád je umrl. Edómski vojvode so bili: vojvoda Timná, vojvoda Aliá, vojvoda Jetét,',
        52: 'vojvoda Oholibáma, vojvoda Elá, vojvoda Pinón,',
        53: 'vojvoda Kenáz, vojvoda Temán, vojvoda Mibcár,',
        54: 'vojvoda Magdiél in vojvoda Irám. To so edómski vojvode.',
    },
    2: {
        1: 'To so Izraelovi sinovi: Ruben, Simeon, Levi, Juda, Isahár, Zábulon,',
        2: 'Dan, Jožef, Benjamin, Neftáli, Gad in Aser.',
        3: 'Judovi sinovi: Er, Onán in Šelá; ki so mu bili trije rojeni od kánaanske hčere Šue. Judov prvorojenec Er pa je bil zloben v Gospodovih očeh; in ga je usmrtil.',
        4: 'Njegova snaha Tamara mu je rodila Pareca in Zeraha. Vseh Judovih sinov je bilo pet.',
        5: 'Parecova sinova: Hecrón in Hamúl.',
        6: 'Zerahovi sinovi: Zimrí, Etán, Hemán, Kalkól in Dardá. Vseh skupaj pet.',
        7: 'Karmíjevi sinovi: Ahár, povzročevalec težav Izraelu, ki se je prekršil s prekleto stvarjo.',
        8: 'Etánovi sinovi: Azarjá.',
        9: 'Tudi sinovi Hecróna, ki so mu bili rojeni: Jerahmeél, Ram, in Kelubaj.',
        10: 'Ram je zaplodil Aminadába in Aminadáb je zaplodil Nahšóna, princa Judovih otrok.',
        11: 'Nahšón je zaplodil Salmóna in Salmón je zaplodil Boaza',
        12: 'in Boaz je zaplodil Obéda in Obéd je zaplodil Jeseja',
        13: 'in Jese je zaplodil prvorojenca Eliába in drugega Abinadába in tretjega Šimá,',
        14: 'četrtega Netanéla, petega Radája,',
        15: 'šestega Ocema, sedmega Davida;',
        16: 'katerega sestri sta bili Cerúja in Abigájila. Cerújini sinovi: Abišáj, Joáb in Asaél, trije.',
        17: 'Abigájila je rodila Amasá; in Amasájev oče je bil Izmaelec Jeter.',
        18: 'Hecrónov sin Kaléb je zaplodil otroke od Azúbe, svoje žene in od Jerióte. Njeni sinovi so tile: Ješer, Šobáb in Ardón.',
        19: 'Ko je bila Azúba mrtva, je Kaléb k sebi vzel Efráto, ki mu je rodila Hura.',
        20: 'Hur je zaplodil Uríja in Uríja je zaplodil Becaléla.',
        21: 'Potem je Hecrón šel v hčer Mahírja, očeta Gileáda, ki jo je poročil, ko je bil star šestdeset let in rodila mu je Segúba.',
        22: 'Segúb je zaplodil Jaíra, ki je imel triindvajset mest v deželi Gileád.',
        23: 'Od njih je vzel Gešur in Arám z Jaírovimi mesti, s Kenátom in njegovimi mesti, celó šestdeset mest. Vsi ti so pripadali sinovom Mahírja, Gileádovega očeta.',
        24: '§ Potem ko je bil Hecrón v Kaléb-efrati mrtev, mu je Hecrónova žena Abíja rodila Ašhúra, očeta Tekóe.',
        25: 'Sinovi Hecrónovega prvorojenca Jerahmeéla so bili: prvorojenec Ram, Buná, Oren, Ocem in Ahíja.',
        26: 'Jerahmeél je imel še drugo ženo, ki ji je bilo ime Atára; bila je Onámova mati.',
        27: 'Sinovi Jerahmeélovega prvorojenca Rama so bili: Máac, Jamín in Eker.',
        28: 'Onámova sinova sta bila: Šamáj in Jadá. In Šamájeva sinova: Nadáb in Abišúr.',
        29: 'Ime Abišúrjeve žene je bilo Abihájila in rodila mu je Ahbána in Molída.',
        30: 'Nadábova sinova: Seled in Apájim, toda Seled je umrl brez otrok.',
        31: 'Apájimovi sinovi: Jiší. Jišíjev sin: Šešán. Šešánovi otroci: Ahláj.',
        32: 'Sinova Šamájevega brata Jadája: Jeter in Jonatan: in Jeter je umrl brez otrok.',
        33: 'Jonatanova sinova: Pelet in Zazá. To so bili Jerahmeélovi sinovi.',
        34: 'Torej Šešán ni imel sinov, temveč hčere. Šešán je imel služabnika, Egipčana, katerega ime je bilo Jarhá.',
        35: 'Šešán je dal svojo hčer svojemu služabniku Jarháju za ženo in rodila mu je Atája.',
        36: 'Atáj je zaplodil Natána in Natán je zaplodil Zabáda',
        37: 'in Zabád je zaplodil Eflála in Eflál je zaplodil Obéda',
        38: 'in Obéd je zaplodil Jehúja in Jehú je zaplodil Azarjája',
        39: 'in Azarjá je zaplodil Heleca in Helec je zaplodil Elasája',
        40: 'in Elasáj je zaplodil Sismája in Sismáj je zaplodil Šalúma',
        41: 'in Šalúm je zaplodil Jekamjája in Jekamjáj je zaplodil Elišamája.',
        42: 'Torej sinovi Jerahmeélovega brata Kaléba so bili njegov prvorojenec Meša, ki je bil oče Zifov; in sinovi Marešá, očeta Hebróna.',
        43: 'Hebrónovi sinovi: Korah, Tapúah, Rekem in Šemaá.',
        44: 'Šemaá je zaplodil Rahama, Jorkoámovega očeta in Rekem je zaplodil Šamája.',
        45: 'Šamájev sin je bil Maón, in Maón je bil Bet Curov oče.',
        46: 'Kalébova priležnica Efá je rodila Harána, Mocája in Gazéza; in Harán je zaplodil Gazéza.',
        47: 'Jahdájevi sinovi so: Regem, Jotám, Gešán, Pelet, Efá in Šáaf.',
        48: 'Kalébova priležnica Maáha je rodila Šeberja in Tirhanája.',
        49: 'Rodila je tudi Šáafa, očeta Madmanája, Ševája, očeta Mahbenája in očeta Gíbee: in Kalébova hči je bila Ahsa.',
        50: 'To so bili sinovi Hurovega sina Kaléba, Efrátinega prvorojenca: Šobál, oče Kirját Jearíma,',
        51: 'Salmón, oče Betlehema, Haríf, oče Bet Gadêrja.',
        52: 'Šobál, oče Kirját Jearíma, je imel sinove: Haroe in polovica Manáhatovcev.',
        53: 'Družine Kirját Jearíma: Jéterjevci, Putéjci, Šuméjci in Mišraíti; iz katerih so izšli Corčani in Eštaólci.',
        54: 'Salmónovi sinovi: Betlehem, Netófčani, Atrót, Joábova hiša in polovica Manáhatovcev in Zorovci.',
        55: 'Družine pisarjev, ki so prebivale pri Jabécu: Tiratéjci, Šimatéjci in Suhéjci. Ti so Kenéjci, ki so prišli iz Hamáta, očeta Rehábove hiše.',
    },
    3: {
        1: 'Torej to so bili Davidovi sinovi, ki so se mu rodili v Hebrónu: prvorojenec Amnón od Jezreélke Ahinóam; drugi Daniel od Karmelčanke Abigájile;',
        2: 'tretji Absalom, sin Maáhe, hčere gešurskega kralja Talmája; četrti Adoníja, sin Hagíte;',
        3: 'peti Šefatjá od Abitále; šesti Jitreám od njegove žene Egle.',
        4: 'Teh šest se mu je rodilo v Hebrónu in tam je kraljeval sedem let in šest mesecev. V Jeruzalemu pa je kraljeval triintrideset let.',
        5: 'Ti so se mu rodili v Jeruzalemu: Šimá, Šobáb, Natán in Salomon, štirje od Batšúe, Amiélove hčere;',
        6: 'tudi Jibhár, Elišamá, Elifélet,',
        7: 'Nogah, Nefeg, Jafíja,',
        8: 'Elišamá, Eljadá in Elifélet, devet.',
        9: 'To so bili vsi Davidovi sinovi, poleg sinov priležnic in njihove sestre Tamare.',
        10: 'Salomonov sin je bil Rehabám, njegov sin Abíja, njegov sin Asá, njegov sin Józafat,',
        11: 'njegov sin Jorám, njegov sin Ahazjá, njegov sin Joáš,',
        12: 'njegov sin Amacjá, njegov sin Azarjá, njegov sin Jotám,',
        13: 'njegov sin Aház, njegov sin Ezekíja, njegov sin Manáse,',
        14: 'njegov sin Amón in njegov sin Jošíja.',
        15: 'Jošíjevi sinovi so bili: prvorojenec Johanán, drugi Jojakím, tretji Sedekíja in četrti Šalúm.',
        16: 'Jojakímova sinova: njegov sin Jehoníja in njegov sin Sedekíja.',
        17: 'Jehoníjevi sinovi: Asír, njegov sin Šaltiél,',
        18: 'tudi Malkirám, Pedajá, Šenacár, Jekamjá, Hošamá in Nedabjá.',
        19: 'Pedajájeva sinova sta bila Zerubabél in Šimí. Zerubabélovi sinovi: Mešulám, Hananjá, njuna sestra Šelomíta,',
        20: 'Hašubá, Ohel, Berehjá, Hasadjá in Jušáb Hesed, pet.',
        21: '§ Hananjájeva sinova: Pelatjája in Ješajá. Refajájevi sinovi, Arnánovi sinovi, Obadjájevi sinovi, Šehanjájevi sinovi.',
        22: 'Šehanjájevi sinovi: Šemajá; in Šemajájevi sinovi: Hatúš, Jigál, Baríah, Nearjá in Šafát, šest.',
        23: 'Nearjájevi sinovi: Eljoenáj, Ezekíja in Azrikám, trije.',
        24: 'Eljoenájevi sinovi so bili: Hodavjá, Eljašíb, Pelajá, Akúb, Johanán, Delajá in Ananí, sedem.',
    },
    4: {
        1: 'Judovi sinovi: Parec, Hecrón, Karmí, Hur in Šobál.',
        2: 'Reajá, sin Šobála, je zaplodil Jahata. Jahat je zaplodil Ahumája in Lahada. To so družine Corčanov.',
        3: 'Ti so bili od očeta Etáma: Jezreél, Jišmá in Jidbáš in ime njihove sestre je bilo Haclelpóni;',
        4: 'Penuél, oče Gedórja in Ecer, oče Hušája. To so sinovi Hura, Efrátinega prvorojenca, očeta Betlehema.',
        5: 'Ašhúr, oče Tekóe, je imel dve ženi, Helo in Naáro.',
        6: 'Naára mu je rodila Ahuzáma, Heferja, Timníja in Ahaštaríja. Ti so bili Naárini sinovi.',
        7: 'Sinovi Hele so bili Ceret, Cohar in Etnán.',
        8: 'Koc je zaplodil Anúba in Cobebá in družine Harúmovega sina Aharhéla.',
        9: 'Jabéc je bil bolj častitljiv kakor njegovi bratje in njegova mati je njegovo ime imenovala Jabéc, rekoč: »Ker sem ga rodila z bridkostjo.«',
        10: 'Jabéc je klical k Izraelovemu Bogu, rekoč: »Oh da bi me ti resnično blagoslovil in povečal moj kraj in da bi bila tvoja roka lahko z menoj in da bi me varoval pred zlom, da me ta ne bi žalostil!« In Bog mu je zagotovil to, kar je zahteval.',
        11: 'Kelúb, brat Šuaha, je zaplodil Mehírja, ki je bil oče Eštóna.',
        12: 'Eštón je zaplodil Betrafá, Paséaha in Tehiná, očeta Ir Naháša. To so možje iz Rehe.',
        13: 'Kenázova sinova: Otniél in Serajá. Otniélovi sinovi: Hatát.',
        14: 'Meonotáj je zaplodil Ofrá. Serajá je zaplodil Joába, očeta doline Ge Haraším, kajti bili so rokodelci.',
        15: 'Sinovi Jefunéjevega sina Kaléba: Iru, Elá in Náam. Elájevi sinovi: celo Kenáz.',
        16: 'Jehalelélovi sinovi: Zif, Zifá, Tirjá in Asarél.',
        17: 'Sinovi Ezra so bili: Jeter, Mered, Efer in Jalón. In ona je rodila Mirjáma, Šamája in Jišbáha, očeta Eštemóa.',
        18: '§ Njegova žena Jehudija je rodila Jereda, Gedórjevega očeta in Heberja, Sohójevega očeta in Jekutiéla, Zanóahovega očeta. Vsi ti so sinovi faraonove hčere Bitije, ki jo vzel Mered.',
        19: 'Sinova njegove žene Hodijáje, Nahamove sestre, Keílin oče Garmít in Maahčán Eštemóa.',
        20: '§ Šimónovi sinovi so bili Amnón, Riná, Ben-Hanán in Tilón. Jišíjeva sinova sta bila Zohét in Ben Zohét.',
        21: 'Sinovi Judovega sina Šelája so bili Er, Lehájev oče in Ladá, Marešájev oče in družine iz hiše tistih, ki so izdelovali tanko laneno platno, iz hiše Ašbéa;',
        22: '§ in Jokím, možje iz Kozébe, Joáš in Saráf, ki so imeli gospostvo v Moábu in Jashubi–lehemu. In to so starodavne stvari.',
        23: '§ Ti so bili lončarji in tisti, ki so prebivali med sadikami in ograjami. Tam so zaradi svojega dela prebivali s kraljem.',
        24: 'Simeonovi sinovi so bili Nemuél, Jamín, Jaríb, Zerah in Šaúl;',
        25: 'njegov sin Šalúm, njegov sin Mibsám, njegov sin Mišmá.',
        26: 'Mišmájevi sinovi: njegov sin Hamuél, njegov sin Zakúr in njegov sin Šimí.',
        27: 'Šimí je imel šestnajst sinov in šest hčera, toda njegovi bratje niso imeli veliko otrok niti se vse njihove družine niso množile, kakor Judovi otroci.',
        28: 'Prebivali so pri Beeršébi, Moládi, Hacár Šuálu,',
        29: 'pri Bilhi, pri Ecemu, pri Toladu,',
        30: 'pri Betuélu, pri Hormi, pri Ciklágu,',
        31: 'pri Bet Markabótu, pri Hacár Susímu, pri Bet Biríju in pri Šaarájimu. To so bila njihova mesta do Davidovega kraljevanja.',
        32: '§ Njihove vasi so bile Etám, Ajin, Rimón, Tohen in Ašán, pet mest',
        33: 'in vse njihove vasi, ki so bile naokoli istih mest, do Báala. To so bila njihova prebivališča in njihov rodovnik.',
        34: 'Mešobáb, Jamléh, Amacjájev sin Jošá,',
        35: 'Joél, Jehú, sin Jošibjája, sin Serajája, sin Asiéla,',
        36: 'Eljoenáj, Jaakóba, Ješohája, Asajá, Adiél, Jesimiél, Benajá,',
        37: 'Zizá, sin Šifíja, sinú Alóna, sinú Jedajája, sinú Šimríja, sinú Šemajája;',
        38: 'ti, omenjeni po svojih imenih, so bili princi v svojih družinah in hiše njihovih očetov so se silno povečale.',
        39: 'Šli so k vhodu Gedórja, celó do vzhodne strani doline, da poiščejo pašnik za svoje trope.',
        40: 'Našli so obilen in dober pašnik in dežela je bila prostrana, tiha in mirna, kajti tisti iz Hama so tam prebivali od davnine.',
        41: 'In tisti, zapisani po imenu, so prišli v dneh Judovega kralja Ezekíja in udarili njihove šotore in prebivališča, ki so bila najdena tam in jih popolnoma uničili do današnjega dne in prebivali so namesto njih, ker je bil tam pašnik za njihove trope.',
        42: 'Nekateri izmed njih, celo izmed Simeonovih sinov, petsto mož, so odšli na gorovje Seír, za svoje poveljnike pa so imeli Pelatjája, Nearjá, Refajá, Uziéla, Jišíjeve sinove.',
        43: 'Udarili so preostanek Amalečanov, ki so pobegnili in tam prebivajo do današnjega dne.',
    },
    5: {
        1: 'Torej sinovi Izraelovega prvorojenca Rubena, (kajti on je bil prvorojenec; toda, ker je omadeževal posteljo svojega očeta, je bila njegova pravica prvorojenstva dana sinovoma Izraelovega sina Jožefa; in rodovnik ni štet po pravici prvorojenstva.',
        2: 'Kajti Juda je prevladal nad svojimi brati in od njega je prišel glavni vladar; toda pravica prvorojenstva je bila Jožefova.)',
        3: 'Sinovi, pravim, od Izraelovega prvorojenca Rubena so bili: Hénoh, Palú, Hecrón in Karmí.',
        4: 'Joélovi sinovi: njegov sin Šemajá, njegov sin Gog, njegov sin Šimí,',
        5: 'njegov sin Miha, njegov sin Reajá, njegov sin Báal,',
        6: 'njegov sin Beerá, ki ga je asirski kralj Tiglát Pilnéser, odvedel ujetega. On je bil princ Rubenovcev.',
        7: 'Njegovi bratje po njihovih družinah, ko je bil preštet rodovnik njihovih rodov, so bili vodja Jeiél, Zeharjá,',
        8: 'Bela, sin Azáza, sinú Šemaá, sinú Joéla, ki je prebival v Aroêrju, celo do Nebója in Báal Meóna;',
        9: 'in proti vzhodu je naseljeval do vstopa v divjino, od reke Evfrat, ker je bila njihova živina pomnožena v deželi Gileád.',
        10: 'V Savlovih dneh so se bojevali s Hagríjevci, ki so padli po njihovi roki in prebivali so v njihovih šotorih po vsej vzhodni deželi Gileád.',
        11: 'Gadovi otroci so prebivali nasproti njih, v deželi Bašán do Salhe;',
        12: 'vodja Joél, naslednji Šafám, Janáj in Šafát v Bašánu.',
        13: 'Njihovi bratje iz hiše njihovih očetov so bili: Mihael, Mešulám, Šeba, Joráj, Jakán, Ziá in Heber, sedem.',
        14: 'Ti so otroci Abihájila, sinú Huríja, sinú Jaróaha, sinú Gileáda, sinú Mihaela, sinú Ješišája, sinú Jahdója, Buzovega sina;',
        15: 'Ahí, sin Abdiéla, Guníjevega sina, vodja hiše njihovih očetov.',
        16: 'Prebivali so v Gileádu, v Bašánu in v njihovih mestih in v vseh predmestjih Šaróna, na njihovih mejah.',
        17: 'Vsi ti so bili šteti po rodovnikih v dneh Judovega kralja Jotáma in v dneh Izraelovega kralja Jerobeáma.',
        18: 'Sinovi Rubena, Gádovcev in polovice Manásejevega rodu izmed hrabrih mož, mož zmožnih, da nosijo ščit in meč in da streljajo z lokom in veščih v vojni, je bilo štiriinštirideset tisoč sedemsto šestdeset, ki so odšli ven na vojsko.',
        19: 'Bojevali so se s Hagríjevci, z Jetúrjem, Nafíšem in Nodábom.',
        20: 'Pomagano jim je bilo zoper njih in Hagríjevci so bili izročeni v njihovo roko in vsi tisti, ki so bili z njimi; kajti v bitki so vpili k Bogu in izprošen je bil od njih, ker so svoje zaupanje položili vanj.',
        21: 'Odvzeli so njihovo živino; od njihovih kamel petdeset tisoč in od ovc dvesto petdeset tisoč in od oslov dva tisoč in od ljudi sto tisoč.',
        22: 'Kajti tam je padlo mnogo umorjenih, ker je bila vojna od Boga. In namesto njih so tam prebivali do ujetništva.',
        23: 'Otroci polovice Manásejevega rodu so prebivali v deželi. Množili so se od Bašána do Báal Hermona in Senírja in do gore Hermon.',
        24: 'Ti so bili poglavarji hiše njihovih očetov, celo Efer, Jiší, Eliél, Azriél, Jeremija, Hodavijá in Jahdiél, močni junaški možje, slavni možje in poglavarji hiše njihovih očetov.',
        25: 'Pregrešili so se zoper Boga svojih očetov in se odšli vlačugat za bogovi ljudstva dežele, ki jih je Bog uničil pred njimi.',
        26: 'Izraelov Bog pa je razvnel duha asirskega kralja Pula in duha asirskega kralja Tiglát Pilnéserja in ta jih je odvedel proč, celo Rubenovce, Gádovce in polovico Manásejevega rodu in jih privedel v Haláh, Habór, Haro in k reki Gozán do današnjega dne.',
    },
    6: {
        1: 'Lévijevi sinovi: Geršón, Kehát in Merarí.',
        2: 'Kehátovi sinovi: Amrám, Jichár, Hebrón in Uziél.',
        3: 'Amrámovi otroci: Aron, Mojzes in Mirjam. Tudi Aronovi sinovi: Nadáb, Abihú, Eleazar in Itamár.',
        4: 'Eleazar je zaplodil Pinhása, Pinhás je zaplodil Abišúa',
        5: 'in Abišúa je zaplodil Bukíja in Bukí je zaplodil Uzíja',
        6: 'in Uzí je zaplodil Zerahjá in Zerahjá je zaplodil Merajóta,',
        7: 'Merajót je zaplodil Amarjá in Amarjá je zaplodil Ahitúba',
        8: 'in Ahitúb je zaplodil Cadóka in Cadók je zaplodil Ahimáaca',
        9: 'in Ahimáac je zaplodil Azarjája in Azarjá je zaplodil Johanána',
        10: 'in Johanán je zaplodil Azarjá (on je ta, ki je opravljal duhovniško službo v templju, ki ga je Salomon zgradil v Jeruzalemu);',
        11: 'Azarjá je zaplodil Amarjá in Amarjá je zaplodil Ahitúba',
        12: 'in Ahitúb je zaplodil Cadóka in Cadók je zaplodil Šalúma',
        13: 'in Šalúm je zaplodil Hilkijá in Hilkijá je zaplodil Azarjá',
        14: 'in Azarjá je zaplodil Serajája in Serajá je zaplodil Jocadáka',
        15: 'in Jocadák je odšel v ujetništvo, ko je Gospod po Nebukadnezarjevi roki odvedel Juda in Jeruzalem.',
        16: 'Lévijevi sinovi: Geršóm, Kehát in Merarí.',
        17: 'To sta imeni Geršómovih sinov: Libni in Šimí.',
        18: 'Kehátovi sinovi so bili: Amrám, Jichár, Hebrón in Uziél.',
        19: 'Meraríjeva sinova: Mahlí in Muší. To so družine Lévijevcev glede na njihove družine.',
        20: 'Od Geršóma: njegov sin Libni, njegov sin Jahat, njegov sin Zimá,',
        21: 'njegov sin Joáh, njegov sin Idó, njegov sin Zerah in njegov sin Jeatraj.',
        22: 'Kehátovi sinovi: njegov sin Aminadáb, njegov sin Korah, njegov sin Asír,',
        23: 'njegov sin Elkaná, njegov sin Abiasáf, njegov sin Asír,',
        24: 'njegov sin Tahat, njegov sin Uriél, njegov sin Uzíjah in njegov sin Šaúl.',
        25: 'Elkanájeva sinova: Amasáj in Ahimót.',
        26: 'Glede Elkaná, Elkanájevi sinovi: njegov sin Cuf, njegov sin Nahat,',
        27: 'njegov sin Eliáb, njegov sin Jerohám in njegov sin Elkaná.',
        28: 'Samuelova sinova: prvorojenec Vašni in Abíja.',
        29: 'Meraríjevi sinovi: Mahlí, njegov sin Libni, njegov sin Šimí, njegov sin Uzá,',
        30: 'njegov sin Šimá, njegov sin Hagijá in njegov sin Asajá.',
        31: 'To so tisti, ki jih je David postavil nad službo pesmi v Gospodovi hiši, potem ko je skrinja imela počitek.',
        32: 'Služili so pred prebivališčem šotorskega svetišča skupnosti s petjem, dokler ni Salomon zgradil Gospodove hiše v Jeruzalemu; potem so čakali na svojo službo glede na svoj red.',
        33: 'Ti so tisti, ki so čakali s svojimi otroci. Izmed sinov Kehátovcev: pevec Hemán, sin Joéla, sinú Šemuéla,',
        34: 'sinú Elkanája, sinú Jeroháma, sinú Eliéla, sinú Tohuja,',
        35: 'sinú Cufa, sinú Elkanája, sinú Mahata, sinú Amasája,',
        36: 'sinú Elkaná, sinú Joéla, sinú Azarjá, sinú Cefanjája,',
        37: 'sinú Tahata, sinú Asírja, sinú Abiasáfa, sinú Koraha,',
        38: 'sinú Jichárja, sinú Keháta, sinú Izraelovega sina Lévija.',
        39: 'Njegov brat Asáf, ki je stal na njegovi desnici, celo Asáf, sin Berehjája, sinú Šimája,',
        40: 'sinú Mihaela, sinú Baasejája, sinú Malkijája,',
        41: 'sinú Etníja, sinú Zeraha, sinú Adajá,',
        42: 'sinú Etána, sinú Zimája, sinú Šimíja,',
        43: 'sinú Jahata, sinú Geršóma, Lévijevega sina.',
        44: 'Njihovi bratje, Meraríjevi sinovi so stali na levi roki: Etán, sin Kišijá, sinú Abdíja, sinú Malúha,',
        45: 'sinú Hašabjája, sinú Amacjá, sinú Hilkijája,',
        46: 'sinú Amcíja, sinú Baníja, sinú Šemerja,',
        47: 'sinú Mahlíja, sinú Mušíja, sinú Meraríja, Lévijevega sina.',
        48: 'Tudi njihovi bratje Lévijevci so bili določeni k vsem vrstam služb šotorskega svetišča Božje hiše.',
        49: 'Toda Aron in njegovi sinovi so darovali na oltarju žgalne daritve in na kadilnem oltarju in bili so določeni za vse delo najsvetejšega prostora in da opravljajo spravo za Izrael, glede na vse, kar je zapovedal Božji služabnik Mojzes.',
        50: 'To so Aronovi sinovi: njegov sin Eleazar, njegov sin Pinhás, njegov sin Abišúa,',
        51: 'njegov sin Bukí, njegov sin Uzí, njegov sin Zerahjá,',
        52: 'njegov sin Merajót, njegov sin Amarjá, njegov sin Ahitúb,',
        53: 'njegov sin Cadók in njegov sin Ahimáac.',
        54: 'Torej to so njihova bivališča po vseh njihovih gradovih in njihovih pokrajinah od Aronovih sinov, od družin Kehátovcev; kajti žreb je bil njihov.',
        55: 'Dali so jim Hebrón v Judovi deželi in njegova predmestja okoli njega.',
        56: 'Toda polja od mesta in njegove vasi so dali Jefunéjevemu sinu Kalébu.',
        57: 'Aronovim sinovom so dali Judova mesta, namreč Hebrón, mesto zatočišča, Libno s svojimi predmestji, Jatír, Eštemóa s svojimi predmestji,',
        58: 'Hilón s svojimi predmestji, Debír s svojimi predmestji,',
        59: 'Ašán s svojimi predmestji in Bet Šemeš s svojimi predmestji.',
        60: 'Od Benjaminovega rodu: Geba s svojimi predmestji, Alémet s svojimi predmestji in Anatót s svojimi predmestji. Vseh njihovih mest po njihovih družinah je bilo trinajst mest.',
        61: 'Kehátovim sinovom, ki so ostali od družine tega rodu, so bila z žrebom dana mesta polovice rodu, namreč od polovice Manásejevega rodu, deset mest.',
        62: 'Geršómovim sinovom po njihovih družinah od Isahárjevega rodu, od Aserjevega rodu, od Neftálijevega rodu in od Manásejevega rodu v Bašánu, trinajst mest.',
        63: 'Meraríjevim sinovim je bilo z žrebom dano, po vseh njihovih družinah, od Rubenovega rodu, od Gadovega rodu in od Zábulonovega rodu dvanajst mest.',
        64: 'Izraelovi otroci so dali Lévijevcem ta mesta z njihovimi predmestji.',
        65: 'Z žrebom so od rodu Judovih otrok, od rodu Simeonovih otrok in od rodu Benjaminovih otrok dali ta mesta, ki so imenovana po njihovih imenih.',
        66: 'Preostanek družin Kehátovih sinov je dobil mesta svojih pokrajin od Efrájimovega rodu.',
        67: 'Od zavetnih mest so jim dali Sihem na gori Efrájim z njegovimi predmestji; dali so tudi Gezer s svojimi predmestji,',
        68: 'Jokmeám s svojimi predmestji, Bet Horón s svojimi predmestji,',
        69: 'Ajalón s svojimi predmestji in Gat Rimón s svojimi predmestji;',
        70: 'od polovice Manásejevega rodu: Anêr s svojimi predmestji, Bileam s svojimi predmestji za družino preostanka Kehátovih sinov.',
        71: 'Geršómovim sinovom je bilo dano od družine polovice Manásejevega rodu Golán v Bašánu s svojimi predmestji in Aštarót s svojimi predmestji;',
        72: 'od Isahárjevega rodu: Kedeš s svojimi predmestji, Daberát s svojimi predmestji,',
        73: 'Ramót s svojimi predmestji in Anem s svojimi predmestji;',
        74: 'od Aserjevega rodu: Mišál s svojimi predmestji, Abdón s svojimi predmestji,',
        75: 'Hukok s svojimi predmestji in Rehób s svojimi predmestji;',
        76: 'od Neftálijevega rodu: Kedeš v Galileji s svojimi predmestji, Hamón s svojimi predmestji in Kirjatájim s svojimi predmestji.',
        77: 'Preostanku Meraríjevih otrok je bilo dano od Zábulonovega rodu: Rimón s svojimi predmestji in Tabor s svojimi predmestji;',
        78: 'in na drugi strani Jordana, pri Jerihi na vzhodni strani Jordana jim je bilo dano od Rubenovega rodu: Becer v divjini s svojimi predmestji, Jahac s svojimi predmestji,',
        79: 'tudi Kedemót s svojimi predmestji in Mefáat s svojimi predmestji;',
        80: 'od Gadovega rodu: Ramót v Gileádu s svojimi predmestji, Mahanájim s svojimi predmestji,',
        81: 'Hešbón s svojimi predmestji in Jazêr s svojimi predmestji.',
    },
    7: {
        1: 'Torej Isahárjevi sinovi so bili: Tolá, Puvá, Jašúb in Šimrón, štirje.',
        2: 'Tolájevi sinovi: Uzí, Refajá, Jeriél, Jahmáj, Jibsám in Šemuél, poglavarji hiše njihovega očeta, namreč od Tolája. Bili so hrabri mogočni možje v svojih rodovih, katerih število je bilo v Davidovih dneh dvaindvajset tisoč šeststo.',
        3: 'Uzíjevi sinovi: Jizrahjá; in Jizrahjájevi sinovi: Mihael, Obadjá, Joél in Jišijá, pet. Vsi izmed njih vodilni možje.',
        4: 'Z njimi, po njihovih rodovih, po hiši njihovih očetov, so bile čete vojakov za vojno, šestintrideset tisoč mož, kajti imeli so veliko žena in sinov.',
        5: 'Njihovi bratje med vsemi Isahárjevimi družinami so bili hrabri mogočni možje, prešteti po vseh njihovih rodovnikih, sedeminosemdeset tisoč.',
        6: 'Benjaminovi sinovi: Bela, Beher in Jediaél, trije.',
        7: 'Belovi sinovi: Ecbón, Uzí, Uziél, Jerimót in Ir, pet; poglavarji hiše njihovih očetov, močni junaški možje; prešteti so bili po njihovih rodovnikih, dvaindvajset tisoč štiriintrideset.',
        8: 'Beherjevi sinovi: Zemirá, Joáš, Eliézer, Eljoenáj, Omri, Jerimót, Abíja, Anatót in Alémet. Vsi ti so Beherjevi sinovi.',
        9: 'Njihovo število po njihovih rodovnikih, po njihovih rodovih, poglavarjev hiš njihovih očetov, močnih junaških mož, je bilo dvajset tisoč dvesto.',
        10: 'Tudi Jediaélovi sinovi: Bilhán. Bilhánovi sinovi: Jeúš, Benjamin, Ehúd, Kenaaná, Zetán, Taršíš in Ahišáhar.',
        11: 'Vseh teh Jediaélovih sinov, po poglavarjih njihovih očetov, močnih junaških mož, je bilo sedemnajst tisoč dvesto vojakov, primernih, da gredo ven na vojsko in bitko.',
        12: 'Tudi Šupím in Hupím, Irova otroka in Huším, Ahêrjevi sinovi.',
        13: 'Neftálijevi sinovi: Jahaciél, Guní, Jecer in Šalúm, Bilhini sinovi.',
        14: 'Manásejevi sinovi: Asriél, ki mu je rodila (toda njegova arámska priležnica je rodila Mahírja, Gileádovega očeta;',
        15: 'in Mahír je vzel za ženo sestro Hupíma in Šupíma, čigar sestri je bilo ime Maáha) in ime drugemu je bilo Celofhád; in Celofhád je imel hčere.',
        16: 'Mahírjeva žena Maáha je rodila sina in njegovo ime imenovala Pereš; in ime njegovega brata je bilo Šereš; njegova sinova pa sta bila Ulám in Rekem.',
        17: 'Ulámovi sinovi: Bedán. To so bili sinovi Gileáda, sinú Mahírja, Manásejevega sina.',
        18: 'Njegova sestra Moléheta je rodila Išhóda, Abiézeja in Mahlája.',
        19: 'Šemidájevi sinovi so bili: Ahján, Šehem, Likhí in Aniám.',
        20: 'Efrájimovi sinovi: Šutélah, njegov sin Bered, njegov sin Tahat, njegov sin Eladá in njegov sin Tahat,',
        21: 'njegov sin Zabád, njegov sin Šutélah, Ecer in Elád, ki so jih usmrtil možje iz Gata, ki so bili rojeni v tej deželi, ker so prišli dol, da odvzamejo njihovo živino.',
        22: 'Njihov oče Efrájim je mnogo dni žaloval in prišli so njegovi bratje, da ga tolažijo.',
        23: 'Ko je odšel k svoji ženi, je spočela, rodila sina in njegovo ime je imenoval Berijá, ker je z njegovo hišo šlo slabo.',
        24: '(Njegova hči je bila Šeêra, ki je zgradila spodnji in zgornji Bet Horón ter Uzén Šeêro.)',
        25: 'Refah je bil njegov sin, tudi Rešef in njegov sin Telah in njegov sin Tahan,',
        26: 'njegov sin Ladán, njegov sin Amihúd, njegov sin Elišamá,',
        27: 'njegov sin Non in njegov sin Ješua.',
        28: 'Njihove posesti in prebivališča so bila Betel in njegova mesta, proti vzhodu Naára, proti zahodu Gezer s svojimi mesti; tudi Sihem in njegova mesta, do Gaze in njenih mest;',
        29: 'in pri mejah Manásejevih otrok, Bet Šeán in njegova mesta, Taanáh in njegova mesta, Megída in njegova mesta ter Dor in njegova mesta. V teh so prebivali otroci Izraelovega sina Jožefa.',
        30: 'Aserjevi sinovi: Jimnáh, Jišvá, Jišví, Berijá in njihova sestra Sêraha.',
        31: 'Berijájeva sinova: Heber in Malkiél, ki je Birzájitov oče.',
        32: 'Heber je zaplodil Jafléta, Šomerja, Hotáma in njihovo sestro Šuo.',
        33: 'Jaflétovi sinovi: Pasáh, Bimhál in Ašvát. To so Jaflétovi sinovi.',
        34: 'Šemerjevi sinovi: Ahí, Rohgá, Hubá in Arám.',
        35: 'Sinovi njegovega brata Heléma: Cofah, Jimná, Šeleš in Amál.',
        36: 'Cofahovi sinovi: Suah, Harnéfer, Šuál, Berí, Jimrá,',
        37: 'Becer, Hod, Šamá, Šilšá, Jitrán in Beerá.',
        38: 'Jeterjevi sinovi: Jefuné, Pispá in Ará.',
        39: 'Ulájevi sinovi: Aráh, Haniél in Ricjá.',
        40: 'Vsi ti so bili Aserjevi otroci, poglavarji njihovih očetnih hiš, izbrani in močni junaški možje, vodje princev. Število tistih, ki so bili po rodovniku zmožni za vojno in bitko, je bilo šestindvajset tisoč mož.',
    },
    8: {
        1: 'Torej Benjamin je zaplodil svojega prvorojenca Bela, drugega Ašbéla in tretjega Ahráha,',
        2: 'četrtega Nohá in petega Rafá.',
        3: 'Belovi sinovi so bili: Adár, Gerá, Abihúd,',
        4: 'Abišúa, Naamán, Ahóah,',
        5: 'Gerá, Šefufán in Hurám.',
        6: 'Ti so Ehúdovi sinovi. To so poglavarji očetov prebivalcev Gebe in odpeljali so jih v Manáhat:',
        7: 'Naamán, Ahíja in Gerá, le-ta jih je pregnal in zaplodil Uzá in Ahihúda.',
        8: 'Šaharájim je zaplodil otroke v moábski deželi, potem ko ju je poslal proč; Hušíma in Baára sta bili njegovi ženi.',
        9: 'Svoji ženi Hódeši je zaplodil Jobába, Cibjá, Meša, Malkáma,',
        10: 'Jeúca, Sahejá in Mirmá. To so bili njegovi sinovi, poglavarji očetov.',
        11: 'S Hušímo je zaplodil Abitúba in Elpáala.',
        12: 'Elpáalovi sinovi: Eber, Mišám in Šamed, ki je zgradil Onó in Lod z njegovimi mesti;',
        13: 'tudi Berijá in Šemaá, ki sta bila poglavarja očetov izmed prebivalcev Ajalóna, ki sta pregnala prebivalce Gata:',
        14: 'Ahjó, Šašák, Jeremót,',
        15: 'Zebadjá, Arád, Ader,',
        16: 'Mihael, Jišpá in Johá, Berijájevi sinovi;',
        17: 'in Zebadjá, Mešulám, Hizkí, Heber,',
        18: 'tudi Jišmeráj, Jizlijá, Jobáb, Elpáalovi sinovi;',
        19: 'in Jakím, Zihrí, Zabdí,',
        20: 'Elienáj, Celetáj, Eliél,',
        21: 'Adajáj, Berajá in Šimrát, Šimíjevi sinovi;',
        22: 'in Jišpán, Eber, Eliél,',
        23: 'Abdón, Zihrí, Hanán,',
        24: 'Hananjá, Elám, Antotijá,',
        25: 'Jifdejá in Penuél, Šašákovi sinovi;',
        26: 'in Šamšeráj, Šeharjá, Ataljá,',
        27: 'Jaarešjá, Elijá in Zihrí, Jerohámovi sinovi.',
        28: 'To so bili poglavarji izmed očetov, po svojih rodovih, vodilni možje. Ti so prebivali v Jeruzalemu.',
        29: 'Pri Gibeónu je prebival oče Gibeóncev, čigar ženi je bilo ime Maáha.',
        30: 'Njegov prvorojenec Abdón, Cur, Kiš, Báal, Nadáb,',
        31: 'Gedór, Ahjó in Zeher.',
        32: 'Miklót je zaplodil Šimája. Tudi ti so s svojimi brati prebivali nasproti njih v Jeruzalemu.',
        33: 'Ner je zaplodil Kiša, Kiš je zaplodil Savla, Savel je zaplodil Jonatana, Malkišúa, Abinadába in Ešbáala.',
        34: 'Jonatanov sin je bil Meríb Báal in Meríb Báal je zaplodil Miha.',
        35: 'Mihovi sinovi so bili Pitón, Meleh, Taréa in Aház.',
        36: 'Aház je zaplodil Jeoadája; in Jeoadá je zaplodil Alémeta, Azmáveta in Zimríja; Zimrí je zaplodil Mocá',
        37: 'in Mocá je zaplodil Binája; njegov sin je bil Rafája, njegov sin Elasáj, njegov sin Acél.',
        38: 'Acél je imel šest sinov, katerih imena so ta: Azrikám, Bohrú, Jišmaél, Šearjá, Obadjá in Hanán. Vsi ti so bili Acélovi sinovi.',
        39: 'Sinovi njegovega brata Ešeka so bili njegov prvorojenec Ulám, drugi Jeúš in tretji Elifélet.',
        40: 'Ulámovi sinovi so bili močni junaški možje, lokostrelci in imel je mnogo sinov in vnukov, sto petdeset. Vsi ti so Benjaminovi sinovi.',
    },
    9: {
        1: 'Tako je bil ves Izrael preštet po rodovnikih. Glej, zapisani so bili v knjigo Izraelovih in Judovih kraljev; [tisti] ki so bili odvedeni v Babilon zaradi svojega prestopka.',
        2: 'Torej prvi prebivalci, ki so prebivali na svojih posestvih, v svojih mestih, so bili Izraelci, duhovniki, Lévijevci in Netinimci.',
        3: 'V Jeruzalemu so od Judovih, Benjaminovih, Efrájimovih otrok in Manáseja prebivali:',
        4: 'Utáj, sin Amihúda, sinú Omrija, sinú Imríja, Baníjevega sina, izmed otrok Judovega sina Pareca.',
        5: 'Izmed Šilčanov: prvorojenec Asajá in njegovi sinovi.',
        6: 'Izmed Zerahovih sinov: Jeuél in njihovi bratje, šeststo devetdeset.',
        7: 'Izmed Benjaminovih sinov: Salú, sin Mešuláma, sinú Hodavijá, Senuájevega sina.',
        8: 'Jerohámov sin Jibnejá in Elá, sin Uzíja, Mihríjevega sina in Mešulám, sin Šefatjája, sinú Reguéla, Jibnijájevega sina',
        9: 'in njihovi bratje, glede na svoje rodove, devetsto šestinpetdeset. Vsi ti možje so bili vodje očetov v hiši svojih očetov.',
        10: 'Izmed duhovnikov: Jedajája, Jojaríb, Jahín,',
        11: 'Azarjá, sin Hilkijá, sinú Mešuláma, sinú Cadóka, sinú Merajóta, Ahitúbovega sina, poveljnika Božje hiše;',
        12: 'in Adajá, sin Jeroháma, sinú Pašhúrja, Malkijájevega sina in Masáj, sin Adiéla, sinú Jahzêraja, sinú Mešuláma, sinú Mešilemóta, Imêrjevega sina',
        13: 'ter njihovi bratje, poglavarji hiše svojih očetov, tisoč sedemsto šestdeset, zelo sposobni možje za službo Božje hiše.',
        14: 'Izmed Lévijevcev: Šemajá, sin Hašuba, sinú Azrikáma, sinú Hašabjája izmed Meraríjevih sinov;',
        15: 'Bakbakár, Hereš, Galál, Matanjá, sin Miha, sinú Zihríja, Asáfovega sina,',
        16: 'Obadjá, sin Šemajája, sinú Galála, Jedutúnovega sina in Berehjá, sin Asája, Elkanájevega sina, ki je prebival v vaseh Netófčanov.',
        17: 'Vratarji so bili Šalúm, Akúb, Talmón, Ahimán in njihovi bratje; Šalúm je bil vodja;',
        18: 'ki so do takrat čakali pri kraljevih velikih vratih proti vzhodu; bili so vratarji v družbi Lévijevih otrok.',
        19: 'Šalúm, sin Koréja, sinú Abiasáfa, Kórahovega sina in njegovi bratje iz hiše njegovega očeta, Kórahovci, so bili nad delom službe, čuvaji velikih vrat šotorskega svetišča. Njihovi očetje, nad Gospodovo vojsko, pa so bili čuvaji vhoda.',
        20: 'Eleazarjev sin Pinhás je bil v preteklem času vladar nad njimi in Gospod je bil z njim.',
        21: 'Mešelemjájev sin Zeharjá je bil vratar vrat šotorskega svetišča skupnosti.',
        22: 'Vseh teh, ki so bili izbrani, da bodo vratarji v velikih vratih, je bilo dvesto dvanajst. Ti so bili prešteti po svojem rodovniku v svojih vaseh, ki sta jih David in videc Samuel odredila v njihovo določeno službo.',
        23: 'Tako so oni in njihovi otroci imeli nadzor velikih vrat Gospodove hiše, namreč hiše šotorskega svetišča, po stražah.',
        24: 'V štirih četrtinah so bili vratarji, proti vzhodu, zahodu, severu in jugu.',
        25: 'Njihovi bratje, ki so bili v svojih vaseh naj bi z njimi prihajali po sedmih dneh, od časa do časa.',
        26: 'Kajti ti Lévijevci, štirje glavni vratarji, so bili v svoji določeni službi in so bili nad sobami in zakladnicami Božje hiše.',
        27: 'Prenočevali so naokoli Božje hiše, ker je bila nad njimi zadolžitev in njim je pripadalo vsakodnevno jutranje odpiranje.',
        28: 'Nekateri izmed njih so imeli zadolžitev strežniških posod, da bi jih prinašali noter in ven po številu.',
        29: 'Tudi nekateri izmed njih so bili določeni, da nadzirajo posode, vse svetiščne priprave, fino moko, vino, olje, dišave in kadila.',
        30: 'Nekateri izmed sinov duhovnikov so iz dišav izdelovali mazilo.',
        31: 'Matitjá, eden izmed Lévijevcev, ki je bil prvorojenec Kórahovca Šalúma, je imel določeno službo nad stvarmi, ki so bile narejene v ponvah.',
        32: 'Ostali izmed njihovih bratov, izmed Kehátovih sinov, so bili nad hlebi navzočnosti, da so jih pripravljali vsak šabat.',
        33: 'To so pevci, glavni izmed Lévijevih očetov, ki so prosti ostali v sobah, kajti pri tem delu so bili zaposleni dan in noč.',
        34: 'Ti glavni Lévijevi očetje so bili vodje po svojih rodovih; ti so prebivali pri Jeruzalemu.',
        35: 'V Gibeónu je prebival Jehiél, oče Gibeóncev, čigar ženi je bilo ime Maáha',
        36: 'in njegov prvorojenec Abdón, potem Cur, Kiš, Báal, Ner, Nadáb,',
        37: 'Gedór, Ahjó, Zeharjá in Miklót.',
        38: 'Miklót je zaplodil Šimá. In tudi ti so prebivali s svojimi brati pri Jeruzalemu, nasproti svojih bratov.',
        39: 'Ner je zaplodil Kiša, Kiš je zaplodil Savla, Savel je zaplodil Jonatana, Malkišúa, Abinadába in Ešbáala.',
        40: 'Jonatanov sin je bil Meríb Báal, in Meríb Báal je zaplodil Miha.',
        41: 'Mihovi sinovi so bili Pitón, Meleh, Tahréa in Aház.',
        42: 'Aház je zaplodil Jara in Jara je zaplodil Alémeta, Azmáveta in Zimríja in Zimrí je zaplodil Mocá',
        43: 'in Mocá je zaplodil Binája, njegov sin Refajá, njegov sin Elasáj, njegov sin Acél.',
        44: 'Acél je imel šest sinov, katerih imena so ta: Azrikám, Bohrú, Jišmaél, Šearjá, Obadjá in Hanán; ti so bili Acélovi sinovi.',
    },
    10: {
        1: 'Torej Filistejci so se borili zoper Izrael, in Izraelovi možje so pobegnili pred Filistejci in umorjeni popadali na gori Gilbói.',
        2: 'Filistejci so zasledovali Savla in njegove sinove; in Filistejci so usmrtili Jonatana, Abinadába in Malkišúa, Savlove sinove.',
        3: 'Bitka je postala huda zoper Savla in lokostrelci so ga zadeli in bil je ranjen od lokostrelcev.',
        4: 'Potem je Savel rekel svojemu nosilcu bojne opreme: »Izvleci svoj meč in me prebodi z njim; da ne bi prišli ti neobrezanci in me zlorabili.« Njegov nosilec bojne opreme pa ni hotel, kajti bil je hudo prestrašen. Tako je Savel vzel meč in se vrgel nanj.',
        5: 'Ko je njegov nosilec bojne opreme videl, da je bil Savel mrtev, se je tudi sam prav tako vrgel na meč in umrl.',
        6: 'Tako je umrl Savel in njegovi trije sinovi in vsa njegova hiša je skupaj umrla.',
        7: 'Ko so vsi možje iz Izraela, ki so bili v dolini, videli, da so oni pobegnili in da so bili Savel in njegovi sinovi mrtvi, potem so zapustili svoja mesta in pobegnili, in prišli so Filistejci ter prebivali v njih.',
        8: 'Pripetilo se je naslednji dan, ko so prišli Filistejci, da oropajo umorjene, da so našli Savla in njegove sinove padle na gori Gilbói.',
        9: 'Ko so ga slekli do golega, so vzeli njegovo glavo, njegovo bojno opremo in [to] poslali naokoli po deželi Filistejcev, da odnesejo novice njihovim malikom in ljudstvu.',
        10: 'Njegovo bojno opremo so položili v hišo svojih bogov, njegovo glavo pa so pritrdili v Dagónovem templju.',
        11: 'Ko so vsi Jabéš Gileádovci slišali vse, kar so Filistejci storili Savlu,',
        12: 'so vstali vsi hrabri možje in odnesli Savlovo truplo in trupla njegovih sinov ter jih prinesli v Jabéš in njihove kosti pokopali pod hrastom v Jabéšu in se postili sedem dni.',
        13: 'Tako je Savel umrl zaradi svojega prestopka, ki ga je zagrešil zoper Gospoda, torej zoper Gospodovo besedo, ki se je ni držal in je tudi spraševal za nasvet nekoga, ki je imel hišnega duha, da poizve o tem,',
        14: 'ni pa poizvedel od Gospoda, zato ga je ta usmrtil in kraljestvo obrnil k Jesejevemu sinu Davidu.',
    },
    11: {
        1: 'Potem se je ves Izrael zbral skupaj k Davidu v Hebrón, rekoč: »Glej, mi smo tvoja kost in tvoje meso.',
        2: 'Poleg tega si bil ti ta v preteklem času, ko je bil Savel kralj, ki si nas vodil ven in privedel v Izrael, in Gospod, tvoj Bog, ti je rekel: ›Ti boš pasel moje ljudstvo Izraela in ti boš vladar nad mojim ljudstvom Izraelom.‹«',
        3: 'Zato so vsi Izraelovi starešine prišli h kralju v Hebrón in David je v Hebrónu z njimi sklenil zavezo pred Gospodom; in mazilili so Davida za kralja nad Izraelom, glede na besedo od Gospoda po Samuelu.',
        4: 'David in ves Izrael so odšli k Jeruzalemu, ki je Jebús, kjer so bili prebivalci dežele Jebusejci.',
        5: 'Prebivalci Jebúsa so rekli Davidu: »Ne boš prišel sèm.« Kljub temu je David zavzel sionski grad, ki je Davidovo mesto.',
        6: 'David je rekel: »Kdorkoli prvi udari Jebusejce bo vodja in poveljnik.« Tako je Cerújin sin Joáb prvi odšel gor in je bil vodja.',
        7: 'David je prebival v gradu, zato so ga imenovali Davidovo mesto.',
        8: 'Okoli je zgradil mesto, celo od Milója naokoli, Joáb pa je popravil preostanek mesta.',
        9: 'Tako je David postajal večji in večji, kajti Gospod nad bojevniki je bil z njim.',
        10: 'Tudi ti so vodje izmed mogočnih mož, ki jih je imel David, ki so se z njim okrepili v njegovem kraljestvu in z vsem Izraelom, da ga postavijo za kralja, glede na Gospodovo besedo, ki je zadevala Izrael.',
        11: 'To pa je število mogočnih mož, ki jih je imel David: Hahmoníjec Jašobám, vodja poveljnikov; svojo sulico je dvignil zoper tristo [in] po njem [so bili] naenkrat umorjeni.',
        12: 'Za njim je bil Eleazar, sin Dodója, Ahóahovca, ki je bil eden izmed treh mogočnih.',
        13: 'Z Davidom je bil pri Pas Damínu in tam so se Filistejci skupaj zbrali za bitko, kjer je bil kos zemljišča poln ječmena; in ljudstvo je pobegnilo pred Filistejci.',
        14: 'Postavila sta se na sredo tega kosa zemljišča, ga osvobodila in usmrtila Filistejce in Gospod jih je rešil z veliko rešitvijo.',
        15: 'Torej trije izmed tridesetih poveljnikov so odšli dol k skali, k Davidu, v votlino Adulám, vojska Filistejcev pa se je utaborila v dolini Rafájim.',
        16: 'David je bil takrat v utrjenem kraju, garnizija Filistejcev pa je bila tedaj pri Betlehemu.',
        17: 'David je zahrepenel in rekel: »Oh da bi mi nekdo dal piti vode iz betlehemskega vodnjaka, ki je pri velikih vratih!«',
        18: 'In trije so se prebili skozi vojsko Filistejcev in zajeli vodo iz betlehemskega vodnjaka, ki je bil pri velikih vratih, jo vzeli in jo prinesli k Davidu, toda David je ni hotel piti, temveč jo je izlil Gospodu',
        19: 'in rekel: »Bog ne daj, da bi storil to stvar. Mar naj bi pil kri teh mož, ki so svoja življenja postavili v nevarnost? Kajti s tveganjem za svoja življenja so jo prinesli.« Zato je ni hotel piti. Te stvari so storili ti trije mogočni.',
        20: 'Joábov brat Abišáj je bil vodja izmed treh. Ker je svojo sulico dvignil proti tristotim, jih usmrtil in imel ime med tremi.',
        21: 'Izmed treh je bil častitljivejši kakor dva, kajti bil je njihov poveljnik, vendar prvih treh ni dosegel.',
        22: 'Jojadájev sin Benajá, sin hrabrega moža iz Kabceéla, ki je storil mnogo dejanj; usmrtil je dva levu podobna moža iz Moába; prav tako je odšel dol in ubil leva v jami na snežen dan.',
        23: 'Ubil je Egipčana, moža visoke postave, pet komolcev visokega. V Egipčanovi roki je bila sulica, podobna tkalčevemu brunu in ta je s palico odšel dol k njemu, iz Egipčanove roke iztrgal sulico in ga usmrtil z njegovo lastno sulico.',
        24: 'Te stvari je storil Jojadájev sin Benajá in imel je ime med tremi najmogočnejšimi.',
        25: 'Glej, bil je častitljiv med tridesetimi, toda ni dosegel prvih treh in David ga je postavil čez svojo stražo.',
        26: 'Hrabri možje izmed vojsk so bili tudi: Joábov brat Asaél, Dodójev sin Elhanán iz Betlehema,',
        27: 'Harórec Šamót, Péletovec Helec,',
        28: 'Irá, sin Tekójčana Ikéša, Anatóčan Abiézer,',
        29: 'Hušán Sibeháj, Ahóahovec Iláj,',
        30: 'Netófčan Mahráj, Baanájev sin Heled, Netófčan,',
        31: 'Ribájev sin Itáj iz Gíbee, ki pripada Benjaminovim otrokom, Piratónec Benajá,',
        32: 'Huráj iz Gáaševih potokov, Arbatéjec Abiél,',
        33: 'Baharuméjec Azmávet, Šaalbónec Eljahbá,',
        34: 'sinovi Guníjevca Hašéna; Jonatan, sin Hararéjca Šagéja,',
        35: 'Ahiám, sin Hararéjca Sahárja, Urov sin Elifál,',
        36: 'Meheréjec Hefer, Péletovec Ahíja,',
        37: 'Karmélčan Hecró, Ezbájev sin Naaráj,',
        38: 'Natánov brat Joél, Hagríjev sin Mibhár,',
        39: 'Amónec Celek, Beeróčan Nahráj, nosilec bojne opreme Cerújinega sina Joába,',
        40: 'Jéterjevec Irá, Jéterjevec Garéb,',
        41: 'Hetejec Urijá, Ahlájev sin Zabád,',
        42: 'Adiná, sin Rubenovca Šizája, poveljnik Rubenovcev in trideseterica z njim,',
        43: 'Maahájev sin Hanán, Mitnéjec Józafat,',
        44: 'Aštaróčan Uzíja, Šamá in Jehiél, sinova Aroêrčana Hotáma,',
        45: 'Šimríjev sin Jediaél in njegov brat Ticéjec Johá,',
        46: 'Mahavéjec Eliél, Elnáamova sinova Jeribáj in Jošavjá, Moábec Jitmá,',
        47: 'Eliél, Obéd in Jaasiél Mecobaján.',
    },
    12: {
        1: 'Torej ti so tisti, ki so prišli k Davidu v Ciklág, medtem ko se je še vedno skrival zaradi Kiševega sina Savla in bili so med mogočnimi možmi, pomočniki vojne.',
        2: 'Oboroženi so bili z loki in uporabljali so lahko tako desno kakor levo roko v metanju kamnov in streljanju puščic iz loka, celó Savlovi bratje iz Benjamina.',
        3: 'Vodja je bil Ahiézer, potem Joáš, sinova Gíbejčana Šemaája, Jeziél in Pelet, Azmávetova sinova, Berahá, Anatóčan Jehú,',
        4: 'Gibeónec Jišmajá, mogočen mož med tridesetimi in nad tridesetimi: Jeremija, Jahaziél, Johanán, Géderčan Jozabád,',
        5: 'Eluzáj, Jerimót, Bealjá, Šemarjá, Harúfčan Šefatjá,',
        6: 'Elkaná, Jišijá, Azarél, Joézer, Jašobám, Kórahovci ter',
        7: 'Joelá in Zebadjá, Jerohámova sinova iz Gedórja.',
        8: 'Izmed Gádovcev so se k Davidu, v utrjen kraj, v divjini, ločili mogočni možje in možje vojne, primerni za boj, ki so lahko ravnali s ščitom in sulico, katerih obrazi so bili podobni obrazom levov in so bili tako nagli kakor srne po gorah:',
        9: 'prvi Ecer, drugi Obadjá, tretji Eliáb,',
        10: 'četrti Mišmaná, peti Jeremija,',
        11: 'šesti Atáj, sedmi Eliél,',
        12: 'osmi Johanán, deveti Elzabád,',
        13: 'deseti Jeremija in enajsti Mahbanáj.',
        14: 'Ti so bili Gadovi sinovi, poveljniki vojske; eden izmed najmanjših je bil nad stotimi in največji nad tisočimi.',
        15: 'Ti so tisti, ki so šli čez Jordan v prvem mesecu, ko je ta poplavil vse svoje bregove, in zapodili so v beg vse tiste iz dolin, tako proti vzhodu kot proti zahodu.',
        16: 'In prišli so izmed Benjaminovih in Judovih otrok k utrjenemu kraju, k Davidu.',
        17: 'David je odšel ven, da jih sreča, jim odgovoril in jim rekel: »Če boste miroljubno prišli k meni, da mi pomagate, se bo moje srce povezalo k vam, toda če boste prišli, da me izdate mojim sovražnikom, ker ni krivice v mojih rokah, [naj] Bog naših očetov pogleda na to in to ošteje.«',
        18: 'Potem je duh prišel nad Amasája, ki je bil vodja poveljnikov in rekel je: »Tvoji smo David in na tvoji strani, Jesejev sin. Mir, mir bodi tebi in mir bodi tvojim pomočnikom, kajti tvoj Bog ti pomaga.« Potem jih je David sprejel in jih postavil za poveljnike čete.',
        19: 'Tam so nekateri prešli od Manáseja k Davidu, ko je s Filistejci prišel zoper Savla, da se bojuje, toda oni jim niso pomagali, kajti filistejski knezi so ga po premisleku poslali proč, rekoč: »Prešel bo k svojemu gospodarju Savlu, da ogrozi naše glave.«',
        20: 'Medtem ko je šel v Ciklág, so od Manáseja k njemu prestopili Adnáh, Jozabád, Jediaél, Mihael, Jozabád, Elihú in Celetáj, poveljniki tisočih, ki so bili iz Manáseja.',
        21: 'Davidu so pomagali zoper krdelo roparjev, kajti vsi so bili močni junaški možje in bili so poveljniki v vojski.',
        22: 'Kajti ob tistem času so dan za dnem prihajali k Davidu, da mu pomagajo, dokler to ni bila velika vojska, podobna Božji vojski.',
        23: 'To so števila čet, ki so bile oborožene za vojno in so prišle k Davidu v Hebrón, da Savlovo kraljestvo obrnejo k njemu, glede na Gospodovo besedo.',
        24: 'Judovih otrok, ki so nosili ščit in sulico, je bilo šest tisoč osemsto oboroženih za vojsko.',
        25: 'Izmed Simeonovih otrok, močnih junaških mož za vojno, sedem tisoč sto.',
        26: 'Izmed Lévijevih otrok štiri tisoč šeststo.',
        27: 'Jojadá je bil voditelj Aroncev in z njim jih je bilo tri tisoč sedemsto,',
        28: 'in Cadók, silno junaški mladenič in dvaindvajset poveljnikov iz hiše njegovega očeta.',
        29: 'Izmed Benjaminovih otrok, Savlovega sorodstva, tri tisoč, kajti do zdaj je večina izmed njih držala stražo Savlove hiše.',
        30: 'Izmed Efrájimovih sinov dvajset tisoč osemsto mogočnih mož, močnih junaških mož, slovečih v hiši svojih očetov.',
        31: 'Izmed polovice Manásejevega rodu osemnajst tisoč [tistih], ki so bili določeni po imenu, da pridejo in postavijo Davida za kralja.',
        32: 'Izmed Isahárjevih otrok, ki so bili možje, ki so imeli razumevanje časov, da vedo, kaj mora Izrael storiti. Njihovih poglavarjev je bilo dvesto, in vsi njihovi bratje so bili pod njihovim poveljem.',
        33: 'Od Zábulona tisti, ki so šli naprej v bitko, izkušeni v vojni, z vsemi vojnimi pripomočki, petdeset tisoč, ki so lahko obdržali položaj; ti niso bili razdeljenega srca.',
        34: 'Od Neftálija tisoč poveljnikov in z njimi sedemintrideset tisoč s ščitom in sulico.',
        35: 'Izmed Danovcev, izkušenih v vojni, osemindvajset tisoč šeststo.',
        36: 'Od Aserja tistih, ki so šli naprej v bitko, izkušenih v vojni, štirideset tisoč.',
        37: 'Na drugi strani Jordana, od Rubenovcev, Gádovcev in od polovice Manásejevega rodu, z vsemi vrstami vojnih priprav za bitko, sto dvajset tisoč.',
        38: 'Vsi ti bojevniki, ki so lahko obdržali položaj, so s popolnim srcem prišli v Hebrón, da postavijo Davida za kralja nad vsem Izraelom, in tudi vsi preostali iz Izraela so bili enega srca, da postavijo Davida za kralja.',
        39: 'Tam so bili z Davidom tri dni, jedli so in pili, kajti njihovi bratje so pripravili zanje.',
        40: 'Poleg tega so tisti, ki so bili blizu njih, celó Isahár, Zábulon in Neftáli, prinesli kruha na oslih, na kamelah, na mulah in na volih ter živež, moko, skupaj stisnjene fige in rozine, vino, olje, vole in obilje ovc, kajti radost je bila v Izraelu.',
    },
    13: {
        1: 'David se je posvetoval s poveljniki nad tisočimi in nad stotimi in z vsakim voditeljem.',
        2: 'David je vsej Izraelovi skupnosti rekel: »Če se vam to zdi dobro in je to od Gospoda, našega Boga, pošljimo vsem našim bratom naokoli, ki so ostali v vsej Izraelovi deželi in z njimi tudi duhovnikom in Lévijevcem, ki so v njihovih mestih in predmestjih, da se bodo lahko zbrali k nam,',
        3: 'in ponovno privedimo k sebi skrinjo našega Boga, kajti v Savlovih dneh nismo povpraševali po njej.«',
        4: 'Vsa skupnost je rekla, da bodo tako storili, kajti stvar je bila pravilna v očeh vsega ljudstva.',
        5: 'Tako je David zbral skupaj ves Izrael, od egiptovskega Šihórja, celo do vstopa v Hamát, da Božjo skrinjo privede iz Kirját Jearíma.',
        6: 'David se je dvignil in ves Izrael v Baálo, to je v Kirját Jearím, ki pripada Judu, da od tam privede Božjo skrinjo Gospoda, ki prebiva med kerubi, katerega ime je imenovano na njej.',
        7: 'Božjo skrinjo so odpeljali na novem vozu iz Abinadábove hiše. Uzá in Ahjó pa sta gnala voz.',
        8: 'David in ves Izrael so igrali pred Bogom z vso svojo močjo, s petjem, harfami, plunkami, tamburini, cimbalami in trobentami.',
        9: 'Ko so prišli na Kidónovo mlatišče, je Uzá iztegnil svojo roko, da pridrži skrinjo, kajti voli so se spotaknili.',
        10: 'Gospodova jeza je bila vžgana zoper Uzá in ga je udaril, ker je svojo roko položil k skrinji in tam je umrl pred Bogom.',
        11: 'David je bil razžaljen, ker je Gospod naredil vrzel nad Uzájem, zato je ta kraj do tega dne imenovan Perec Uzá.',
        12: 'David se je tisti dan bal Boga, rekoč: »Kako naj Božjo skrinjo pripeljem k sebi domov?«',
        13: 'Tako David skrinje ni pripeljal k sebi domov, v Davidovo mesto, temveč jo je odnesel stran, v hišo Gitéjca Obéd Edóma.',
        14: 'Božja skrinja je ostala tri mesece z družino Obéd Edóma v njegovi hiši. Gospod je blagoslovil hišo Obéd Edóma in vse, kar je ta imel.',
    },
    14: {
        1: 'Torej kralj Hirám iz Tira je poslal poslance k Davidu in cedrov les z zidarji in tesarji, da mu zgradijo hišo.',
        2: 'David je zaznal, da ga je Gospod potrdil za kralja nad Izraelom, kajti njegovo kraljestvo je bilo visoko povzdignjeno zaradi njegovega ljudstva Izraela.',
        3: 'David si je v Jeruzalemu vzel več žena in David je zaplodil več sinov in hčera.',
        4: 'Torej to so imena njegovih otrok, ki jih je imel v Jeruzalemu: Šamúa, Šobáb, Natán, Salomon,',
        5: 'Jibhár, Elišúa, Elpélet,',
        6: 'Nogah, Nefeg, Jafíja,',
        7: 'Elišamá, Beeljadá in Elifálet.',
        8: 'Ko so Filistejci slišali, da je bil David maziljen za kralja nad vsem Izraelom, so vsi Filistejci odšli gor, da poiščejo Davida. David pa je slišal o tem in odšel ven zoper njih.',
        9: 'Filistejci so prišli in se razporedili po dolini Rafájim.',
        10: 'David je poizvedel od Boga, rekoč: »Ali naj grem gor zoper Filistejce? Ali jih boš izročil v mojo roko?« Gospod mu je rekel: »Pojdi gor, kajti izročil jih bom v tvojo roko.«',
        11: 'Tako so prišli gor v Báal Peracím in David jih je tam udaril. Potem je David rekel: »Bog je po moji roki pridrl nad moje sovražnike, kakor izbruhnejo vode,« zato so ime tega kraja imenovali Báal Peracím.',
        12: 'Ko so tam pustili svoje bogove, je David dal zapoved in sežgali so jih v ognju.',
        13: 'Filistejci pa so se ponovno razporedili po dolini.',
        14: 'Zato je David ponovno poizvedel od Boga in Bog mu je rekel: »Ne pojdi gor za njimi. Obrni se proč od njih in pridi nadnje nasproti murvinih dreves.',
        15: 'Zgodilo se bo, ko boš zaslišal zvok hoje po vrhovih murvinih dreves, da boš tedaj odšel ven na bitko, kajti Bog je šel naprej pred teboj, da udari vojsko Filistejcev.«',
        16: 'David je torej storil, kakor mu je Bog zapovedal in udarili so vojsko Filistejcev od Gibeóna, celo do Gazerja.',
        17: 'Davidova slava se je razširila po vseh deželah in Gospod je nad vse narode privedel strah pred njim.',
    },
    15: {
        1: 'David si je v Davidovem mestu zgradil hiše in pripravil kraj za Božjo skrinjo in zanjo razpel šotor.',
        2: 'Potem je David rekel: »Božje skrinje ne bi smel nositi nihče razen Lévijevcev, kajti njih je Gospod izbral, da nosijo Božjo skrinjo in da mu služijo na veke.«',
        3: 'David je skupaj zbral ves Izrael v Jeruzalemu, da prinese gor Gospodovo skrinjo na kraj, ki ga je pripravil zanjo.',
        4: 'David je zbral Aronove otroke in Lévijevce.',
        5: 'Izmed Kehátovih sinov vodja Uriéla in sto dvajset njegovih bratov;',
        6: 'izmed Meraríjevih sinov vodja Asajája in dvesto dvajset njegovih bratov;',
        7: 'izmed Geršómovih sinov vodja Joéla in sto trideset njegovih bratov;',
        8: 'izmed Elicafánovih sinov vodja Šemajá in dvesto njegovih bratov;',
        9: 'izmed Hebrónovih sinov vodja Eliéla in osemdeset njegovih bratov;',
        10: 'izmed Uziélovih sinov vodja Aminadába in sto dvanajst njegovih bratov.',
        11: 'David je dal poklicati Cadóka, duhovnika Abjatárja in Lévijevce Uriéla, Asajá, Joéla, Šemajá, Eliéla in Aminadába',
        12: 'ter jim rekel: »Vi ste vodje očetov Lévijevcev. Posvetite se tako vi kakor vaši bratje, da boste lahko prinesli gor skrinjo Gospoda, Izraelovega Boga, na kraj, ki sem ga pripravil zanjo.',
        13: 'Kajti ker tega niste najprej storili, je Gospod, naš Bog, nad nami naredil vrzel, ker ga nismo iskali po predpisanem redu.«',
        14: 'Tako so se duhovniki in Lévijevci posvetili, da prinesejo gor skrinjo Gospoda, Izraelovega Boga.',
        15: 'Lévijevi otroci so na svojih ramenih nosili Božjo skrinjo z njenima drogovoma v njej, kakor je zapovedal Mojzes, glede na Gospodovo besedo.',
        16: 'David je spregovoril vodju Lévijevcev, da določi svoje brate, da bodo pevci z glasbenimi instrumenti, plunkami, harfami in cimbalami, z dvigovanjem zvenečega radostnega glasu.',
        17: 'Tako so Lévijevci določili Joélovega sina Hemána in izmed njegovih bratov Berehjájevega sina Asáfa in izmed Meraríjevih sinov, njihovih bratov, Kušajájevega sina Etána',
        18: '§ in z njimi njihove brate druge stopnje: Zeharjája, Bena, Jaaziéla, Šemiramóta, Jehiéla, Uníja, Eliába, Benajája, Maasejája, Matitjája, Elifeléhuja, Miknejája, Obéd Edóma in Jeiéla, vratarje.',
        19: 'Tako so bili pevci Hemán, Asáf in Etán določeni, da igrajo na cimbale iz brona,',
        20: 'Zeharjá, Jaaziél, Šemiramót, Jehiél, Uní, Eliáb, Maasejá in Benajá s plunkami na sopran,',
        21: 'in Matitjá, Elifeléhu, Miknejá, Obéd Edóm, Jeiél in Azazjá s harfami v oktavi, da vodijo.',
        22: 'Kenanjá, vodja Lévijevcev, je bil za pesem. Poučil je glede pesmi, ker je bil vešč.',
        23: 'Berehjá in Elkaná sta bila vratarja za skrinjo.',
        24: 'Duhovniki Šebanjá, Józafat, Netanél, Amasáj, Zeharjá, Benajá in Eliézer so s trobentami trobili pred Božjo skrinjo; Obéd Edóm in Jehijá pa sta bila vratarja za skrinjo.',
        25: 'Tako so David, Izraelove starešine in tisočniki odšli, da iz hiše Obéd Edóma z radostjo prinesejo gor Gospodovo skrinjo zaveze.',
        26: 'Pripetilo se je, ko je Bog pomagal Lévijevcem, da so nosili skrinjo Gospodove zaveze, da so darovali sedem bikcev in sedem ovnov.',
        27: 'David je bil oblečen s svečanim oblačilom iz tankega lanenega platna in vsi Lévijevci, ki so nosili skrinjo, pevci in Kenanjá, mojster pesmi s pevci; tudi David je imel na sebi efód iz lana.',
        28: 'Tako je ves Izrael prinesel gor Gospodovo skrinjo zaveze z vriskanjem, z zvokom kornéta, s trobentami, cimbalami in igrali so s plunkami in harfami.',
        29: 'Pripetilo se je, medtem ko je Gospodova skrinja prišla v Davidovo mesto, da je Savlova hči Mihála, zroč skozi okno, videla kralja Davida plesati in igrati in ga v svojem srcu prezirala.',
    },
    16: {
        1: 'Tako so prinesli Božjo skrinjo in jo postavili na sredo šotora, ki ga je kralj David postavil zanjo ter pred Bogom darovali žgalne daritve in mirovne daritve.',
        2: 'Ko je David končal žrtvovanje žgalnih daritev in mirovnih daritev, je v Gospodovem imenu blagoslovil ljudstvo.',
        3: 'Vsakemu iz Izraela, tako moškemu kakor ženski, vsakemu je razdelil hleb kruha, dober kos mesa in flaškon vina.',
        4: 'Nekatere izmed Lévijevcev je določil, da služijo pred Gospodovo skrinjo in da se spominjajo, se zahvaljujejo in hvalijo Gospoda, Izraelovega Boga:',
        5: 'vodja Asáfa in poleg njega Zeharjá, Jeiéla, Šemiramóta, Jehiéla, Matitjája, Eliába, Benajája in Obéd Edóma; in Jeiéla s plunkami in harfami, toda Asáf je igral na cimbale;',
        6: 'tudi duhovnika Benajája in Jahaziéla s trobentami nenehno pred skrinjo Božje zaveze.',
        7: 'Potem je na ta dan David prvič izročil ta psalm v roko Asáfa in njegovih bratov, da se zahvalijo Gospodu.',
        8: 'Zahvaljujte se Gospodu, kličite njegovo ime, med ljudstvom razglašajte njegova dela.',
        9: 'Prepevajte mu, prepevajte mu psalme, govorite o vseh njegovih čudovitih delih.',
        10: 'Ponašajte se z njegovim svetim imenom. Naj se veseli srce tistih, ki iščejo Gospoda.',
        11: 'Iščite Gospoda in njegovo moč, neprenehoma iščite njegov obraz.',
        12: 'Spominjajte se njegovih čudovitih del, ki jih je storil, njegovih čudežev in sodb njegovih ust;',
        13: 'oh vi seme Izraela, njegovega služabnika, vi Jakobovi otroci, njegovi izbranci.',
        14: 'On je Gospod, naš Bog, njegove sodbe so po vsej zemlji.',
        15: 'Vedno se zavedajte njegove zaveze, besede, katero je zapovedal tisočim rodovom,',
        16: 'celo zaveze, ki jo je sklenil z Abrahamom in njegove prisege Izaku',
        17: 'in isto je potrdil Jakobu za zakon in Izraelu za večno zavezo,',
        18: 'rekoč: »Tebi bom dal kánaansko deželo, žreb vaše dediščine,«',
        19: 'ko vas je bilo le malo, celo peščica in tujci v njej.',
        20: 'Ko so hodili od naroda k narodu in od enega kraljestva k drugemu ljudstvu,',
        21: 'nobenemu človeku ni pustil, da jim stori krivico; da, zaradi njih je grajal kralje,',
        22: 'rekoč: »Ne dotikajte se mojih maziljencev in mojim prerokom ne delajte hudega.«',
        23: 'Poj Gospodu, vsa zemlja, iz dneva v dan naznanjaj njegovo rešitev duše.',
        24: 'Oznanjajte njegovo slavo med pogani, njegova čudovita dela med vsemi narodi.',
        25: '§ Kajti velik je Gospod in silno naj bo hvaljen. Njega se je treba bati nad vsemi bogovi.',
        26: 'Kajti vsi bogovi ljudstva so maliki, toda Gospod je naredil nebesa.',
        27: 'Slava in čast sta v njegovi prisotnosti, moč in veselje sta na njegovem kraju.',
        28: 'Dajajte Gospodu, ve sorodstva ljudstev, dajajte Gospodu slavo in moč.',
        29: 'Dajajte Gospodu slavo, primerno njegovemu imenu, prinesite daritev in pridite predenj. Obožujte Gospoda v lepoti svetosti.',
        30: 'Boj se pred njim, vsa zemlja. Tudi zemeljski [krog] bo trden, ki ne bo omajan.',
        31: 'Naj bodo nebesa vesela in naj se zemlja veseli, in ljudje naj govorijo med narodi: » Gospod kraljuje.«',
        32: 'Naj buči morje in njegova polnost. Naj se polja veselijo in vse, kar je na njih.',
        33: 'Potem bodo gozdna drevesa prepevala ob Gospodovi prisotnosti, ker on prihaja, da sodi zemljo.',
        34: 'Oh zahvaljujte se Gospodu, ker je dober, kajti njegovo usmiljenje traja za vedno.',
        35: 'Recite: »Reši nas, oh Bog rešitve naših duš, zberi nas skupaj in nas osvobodi pred pogani, da se bomo lahko zahvaljevali tvojemu svetemu imenu in slavili v tvoji hvali.',
        36: 'Blagoslovljen bodi Gospod, Izraelov Bog na veke vekov.« In vse ljudstvo je reklo: »Amen« in hvalilo Gospoda.',
        37: 'Tako je tam, pred skrinjo Gospodove zaveze, pustil Asáfa in njegove brate, da nenehno služijo pred skrinjo, kakor je zahtevalo vsakodnevno delo,',
        38: 'in Obéd Edóma z oseminšestdesetimi njihovimi brati; tudi Jedutúnovega sina Obéd Edóma in Hosája, da bosta vratarja;',
        39: 'in duhovnika Cadóka in njegove brate duhovnike pred Gospodovim šotorskim svetiščem na visokem kraju, ki je bil pri Gibeónu,',
        40: 'da darujejo žgalne daritve Gospodu na oltarju, nenehne žgalne daritve, jutranje in večerne in da storijo glede na vse, kar je pisano v Gospodovi postavi, ki jo je zapovedal Izraelu;',
        41: 'in z njimi Hemána, Jedutúna in druge, ki so bili izbrani, ki so bili določeni po imenu, da se zahvaljujejo Gospodu, ker njegovo usmiljenje traja večno;',
        42: 'in z njimi Hemána in Jedutúna s trobentami in cimbalami za tiste, da bi igrali in z Božjimi glasbenimi instrumenti. Jedutúnovi sinovi pa so bili vratarji.',
        43: 'In vse ljudstvo je odšlo vsak človek k svoji hiši, in David se je vrnil, da blagoslovi svojo hišo.',
    },
    17: {
        1: 'Pripetilo se je torej, medtem ko je David sedel v svoji hiši, da je David rekel preroku Natánu: »Glej, jaz prebivam v cedrovi hiši, toda skrinja Gospodove zaveze ostaja pod zavesami.«',
        2: 'Potem je Natán rekel Davidu: »Stôri vse, kar je v tvojem srcu, kajti Bog je s teboj.«',
        3: 'Iste noči se je pripetilo, da je Božja beseda prišla k Natánu, rekoč:',
        4: '»Pojdi in povej mojemu služabniku Davidu: ›Tako govori Gospod: ›Ti mi ne boš gradil hiše, da prebivam v njej,',
        5: 'kajti nisem prebival v hiši od dne, ko sem Izraela privedel gor, do današnjega dne, temveč sem šel od šotora k šotoru in od enega šotorskega svetišča k drugemu.',
        6: 'Kjerkoli sem hodil z vsem Izraelom, sem mar spregovoril besedo kateremukoli izmed Izraelovih sodnikov, ki sem jim zapovedal, da pasejo moje ljudstvo, rekoč: ›Zakaj mi niste zgradili cedrove hiše?‹',
        7: 'Zdaj boš torej tako povedal mojemu služabniku Davidu: ›Tako govori Gospod nad bojevniki: ›Vzel sem te iz staje za ovce, celó od sledenja ovcam, da bi bil vladar nad mojim ljudstvom Izraelom,',
        8: 'in s teboj sem bil kjerkoli si hodil in pred teboj sem iztrebil vse tvoje sovražnike in ti naredil ime, podobno imenu velikih mož, ki so na zemlji.',
        9: 'Prav tako bom določil kraj za svoje ljudstvo Izrael in jih zasadil in bodo prebivali na svojem kraju in ne bodo več seljeni niti jih ne bodo več pustošili otroci zlobnosti kakor poprej',
        10: 'in odkar sem zapovedal sodnikom, naj bodo nad mojim ljudstvom Izraelom. Poleg tega bom podjarmil vse tvoje sovražnike. Nadalje ti povem še, da ti bo Gospod zgradil hišo.',
        11: 'Zgodilo se bo, ko bodo tvoji dnevi pretekli, da moraš oditi, da boš s svojimi očeti, da bom obudil tvoje seme za teboj, ki bo izmed tvojih sinov in jaz bom utrdil njegovo kraljestvo.',
        12: 'Zgradil mi bo hišo in njegov prestol bom utrdil na veke.',
        13: 'Jaz bom njegov oče in on bo moj sin. Svoje milosti ne bom odvzel od njega, kakor sem jo odvzel tistemu, ki je bil pred teboj,',
        14: 'temveč ga bom postavil v svoji hiši in v svojem kraljestvu na veke in njegov prestol bo utrjen na vékomaj.‹«',
        15: 'Glede na vse te besede in glede na vse to videnje, tako je Natán govoril Davidu.',
        16: 'Kralj David je prišel in se usedel pred Gospodom ter rekel: »Kdo sem jaz, oh Gospod Bog in kaj je moja hiša, da si me privedel sèm?',
        17: 'Vendar je bila to majhna stvar v tvojih očeh, oh Bog, kajti govoril si tudi o hiši svojega služabnika za oddaljeni čas, ki pride in si se ozrl name glede na stan človeka visoke stopnje, oh Gospod Bog.',
        18: 'Kaj ti lahko David še govori glede časti tvojega služabnika? Kajti poznaš svojega služabnika.',
        19: 'Oh Gospod, zaradi svojega služabnika in glede na svoje lastno srce, si storil vso to veličino v tem, da si dal spoznati vse te velike stvari.',
        20: 'Oh Gospod, nobenega ni podobnega tebi niti ni nobenega Boga poleg tebe, glede na vse, kar smo slišali s svojimi ušesi.',
        21: 'Kateri narod na zemlji je podoben tvojemu ljudstvu Izraelu, ki ga je Bog šel odkupit, da postane njegovo lastno ljudstvo, da si si naredil ime veličine in strašnosti s pregonom narodov izpred svojega ljudstva, ki si ga odkupil iz Egipta?',
        22: 'Kajti svojemu ljudstvu Izraelu si storil, da bo tvoje lastno ljudstvo na veke; in ti, Gospod, postajaš njihov Bog.',
        23: 'Zato sedaj, Gospod, naj bo stvar, ki si jo govoril glede svojega služabnika in glede njegove hiše, utrjena na veke in stôri, kakor si rekel.',
        24: 'Naj bo to celo utrjeno, da bo tvoje ime lahko poveličano na veke, rekoč: › Gospod nad bojevniki je Izraelov Bog, celó Bog Izraelu‹ in naj bo hiša tvojega služabnika Davida utrjena pred teboj.',
        25: 'Kajti ti, oh moj Bog, si povedal svojemu služabniku, da mu hočeš zgraditi hišo, zato je tvoj služabnik v svojem srcu našel, da moli pred teboj.',
        26: 'In sedaj, Gospod, ti si Bog in to dobroto si obljubil svojemu služabniku.',
        27: 'Zdaj naj ti torej to ugaja, da blagosloviš hišo svojega služabnika, da bo ta lahko pred teboj na veke, kajti ti blagoslavljaš, oh Gospod in to bo blagoslovljeno na veke.«',
    },
    18: {
        1: 'Torej po tem se je pripetilo, da je David udaril Filistejce in jih podjarmil in iz roke Filistejcev vzel Gat in njegova mesta.',
        2: 'Udaril je Moáb in Moábci so postali Davidovi služabniki in prinašali darila.',
        3: 'David je udaril Hadarézerja, kralja Cobe v Hamátu, medtem ko je šel, da si utrdi svoje gospostvo pri reki Evfratu.',
        4: 'David mu je vzel tisoč bojnih vozov in sedem tisoč konjenikov in dvajset tisoč pešcev. David je tudi prerezal Ahilove tetive vsem konjem bojnega voza, toda izmed njih je prihranil sto bojnih vozov.',
        5: 'Ko so Sirci iz Damaska prišli pomagat Hadarézerju, kralju iz Cobe, je David med Sirci usmrtil dvaindvajset tisoč mož.',
        6: 'Potem je David v sirskem Damasku postavil garnizije in Sirci so postali Davidovi služabniki in prinašali darila. Tako je Gospod varoval Davida kamorkoli je šel.',
        7: 'David je vzel ščite iz zlata, ki so bili na Hadarézerjevih služabnikih in jih prinesel v Jeruzalem.',
        8: 'Podobno je iz Tibháta in iz Kuna, Hadarézerjevih mest, David prinesel zelo veliko brona, s katerim je Salomon naredil bronasto morje, stebra in bronaste posode.',
        9: 'Torej ko je kralj Tov iz Hamáta slišal kako je David udaril vso vojsko Hadarézerja, kralja iz Cobe,',
        10: 'je poslal svojega sina Hadoráma h kralju Davidu, da poizve o njegovi blaginji in da mu čestita, ker se je boril zoper Hadarézerja in ga udaril (kajti Hadarézer je bil v vojni s Tovjem) in z njim vse vrste posod iz zlata, srebra in brona.',
        11: 'Tudi te je kralj David posvetil Gospodu, s srebrom in zlatom, ki ga je prinesel iz vseh teh narodov: iz Edóma, Moába, od Amónovih otrok, od Filistejcev in od Amáleka.',
        12: '§ Poleg tega je Cerújin sin Abišáj, usmrtil osemnajst tisoč Edómcev v slani dolini.',
        13: 'Postavil je garnizije v Edómu in vsi Edómci so postali Davidovi služabniki. Tako je Gospod varoval Davida kamorkoli je šel.',
        14: 'Tako je David kraljeval nad vsem Izraelom in izvrševal sodbo ter pravico med vsem svojim ljudstvom.',
        15: 'Cerújin sin Joáb je bil nad vojsko in Ahilúdov sin Józafat [je bil] letopisec.',
        16: 'Ahitúbov sin Cadók in Abjatárjev sin Abiméleh sta bila duhovnika, Šavšá pa je bil pisar.',
        17: 'Jojadájev sin Benajá je bil nad Keretéjci in Péletovci, Davidovi sinovi pa so bili vodje okoli kralja.',
    },
    19: {
        1: 'Torej po tem se je pripetilo, da je umrl Naháš, kralj Amónovih otrok in namesto njega je zakraljeval njegov sin.',
        2: 'David je rekel: »Izkazal bom prijaznost Naháševemu sinu Hanúnu, ker je njegov oče izkazal prijaznost meni.« In David je poslal poslance, da ga potolažijo glede njegovega očeta. Tako so Davidovi služabniki prišli v deželo Amónovih otrok k Hanúnu, da ga potolažijo.',
        3: 'Toda princi Amónovih otrok so Hanúnu rekli: »Misliš, da je David spoštoval tvojega očeta, da ti je poslal tolažnike? Mar niso njegovi služabniki prišli k tebi, da preiščejo, preobrnejo in si ogledajo deželo?«',
        4: 'Zato je Hanún prijel Davidove služabnike, jih obril in njihove obleke odrezal po sredi, tik poleg njihovih zadnjic in jih odposlal proč.',
        5: 'Potem so nekateri odšli in Davidu povedali, kako so bili možje postreženi. In poslal je, da jih sreča, kajti možje so bili silno osramočeni. Kralj je rekel: »Ostanite pri Jerihi, dokler vam brade ne zrastejo, potem se vrnite.«',
        6: 'Ko so Amónovi otroci videli, da so Davidu postali zoprni, so Hanún in Amónovi otroci poslali tisoč talentov srebra, da si iz Mezopotamije, iz sirske Maáhe in Cobe najamejo bojne vozove in konjenike.',
        7: 'Tako so najeli dvaintrideset tisoč bojnih vozov, kralja Maáhe in njegovo ljudstvo, ki so prišli in se utaborili pred Médebo. In Amónovi otroci so se zbrali skupaj iz svojih mest in prišli na bitko.',
        8: 'Ko je David slišal o tem, je poslal Joába in vso vojsko mogočnih mož.',
        9: 'Amónovi otroci so prišli ven in se pred velikimi vrati mesta postrojili v bitko. Kralji, ki so prišli, pa so bili posebej na polju.',
        10: 'Torej ko je Joáb videl, da je bila bitka zoper njega postavljena spredaj in zadaj, je izmed vseh izbral izbrane Izraelove in jih postrojil zoper Sirce.',
        11: 'Preostanek ljudstva pa je izročil v roko svojega brata Abišája, in ti so se postrojili zoper Amónove otroke.',
        12: 'Rekel je: »Če bodo Sirci zame premočni, potem mi boš ti pomagal, toda če bodo Amónovi otroci premočni zate, potem bom jaz pomagal tebi.',
        13: 'Bodi odločnega poguma in se junaško obnašajva za naše ljudstvo in za mesta našega Boga. Gospod pa naj stori to, kar je dobro v njegovem pogledu.«',
        14: 'Tako se je Joáb in ljudstvo, ki je bilo z njim, približalo pred Sirce k bitki, ti pa so pobegnili pred njim.',
        15: 'Ko so Amónovi otroci videli, da so Sirci pobegnili, so tudi sami pobegnili pred njegovim bratom Abišájem in vstopili v mesto. Potem je Joáb prišel v Jeruzalem.',
        16: 'Ko pa so Sirci videli, da so bili pred Izraelom poraženi, so poslali poslance in pripeljali Sirce, ki so bili onkraj reke; in Šopáh, poveljnik Hadarézerjeve vojske, je šel pred njimi.',
        17: 'To je bilo povedano Davidu in ta je zbral ves Izrael, prečkal Jordan in prišel nadnje in se postrojil v bitko zoper njih. Torej, ko se je David postrojil v bitko zoper Sirce, so se ti bojevali z njim.',
        18: 'Toda Sirci so zbežali pred Izraelom in David jih je izmed Sircev usmrtil sedem tisoč mož, ki so se bojevali na bojnih vozovih in štirideset tisoč pešcev in ubil poveljnika vojske Šopáha.',
        19: 'Ko so Hadarézerjevi služabniki videli, da so bili pred Izraelom poraženi, so z Davidom sklenili mir in postali njegovi služabniki; niti Sirci niso hoteli več pomagati Amónovim otrokom.',
    },
    20: {
        1: 'Pripetilo se je, potem ko je minilo leto, ob času, ko gredo kralji na bitko, da je Joáb vodil moč vojske in opustošil deželo Amónovih otrok in prišel ter oblegal Rabo. Toda David je ostal v Jeruzalemu. In Joáb je udaril Rabo ter jo uničil.',
        2: 'David je snel krono njihovega kralja iz njegove glave in spoznal, da tehta talent zlata in v njej so bili dragoceni kamni, in ta je bila postavljena na Davidovo glavo. In iz mesta je prinesel tudi silno mnogo plena.',
        3: '§ Ljudstvo, ki je bilo v njem, je privedel ven in jih razsekal z žagami, branami iz železa in sekirami. Celo tako je David postopal z vsemi mesti Amónovih otrok. In David in vse ljudstvo se je vrnilo v Jeruzalem.',
        4: 'Pripetilo se je za tem, da se je vzdignila vojna s Filistejci pri Gezerju. Takrat je Hušán Sibeháj usmrtil Sipája, ki je bil izmed otrok velikana; in bili so podjarmljeni.',
        5: 'Ponovno je bila vojna s Filistejci. Jaírov sin Elhanán je usmrtil Lahmíja, brata Gitéjca Goljata, katerega kopjišče je bilo podobno tkalčevemu brunu.',
        6: 'Ponovno je bila vojna pri Gatu, kjer je bil mož visoke postave, katerega prstov in palcev je bilo štiriindvajset, šest na vsaki roki in šest na vsakem stopalu in tudi ta je bil sin velikana.',
        7: 'Toda ko je izzival Izraela, ga je Jonatan, Šimájajev sin, Davidov brat, usmrtil.',
        8: 'Ti so bili rojeni velikanu v Gatu in padli so po Davidovi roki in po roki njegovih služabnikov.',
    },
    21: {
        1: 'Satan je vstal zoper Izraela in spodbudil Davida, da prešteje Izraela.',
        2: 'In David je rekel Joábu ter voditeljem ljudstva: »Pojdite, preštejte Izraela od Beeršéba celo do Dana in njihovo število prinesite k meni, da ga bom lahko vedel.«',
        3: 'Joáb je odgovoril: » Gospod naj naredi svoje ljudstvo stokrat tako številno, kot jih je, toda moj gospod kralj, ali niso vsi služabniki mojega gospoda? Zakaj potem moj gospod zahteva to stvar? Zakaj bo on razlog prekrška Izraelu?«',
        4: 'Kljub temu je kraljeva beseda prevladala proti Joábovi. Zato je Joáb odpotoval, šel skozi ves Izrael in prišel v Jeruzalem.',
        5: 'Joáb je Davidu izročil vsoto ljudstva. In vseh iz Izraela je bilo milijon sto tisoč, ki so izdirali meč, in Juda je bilo štiristo sedemdeset tisoč mož, ki so izdirali meč.',
        6: 'Toda Lévijevce in Benjamina pa ni prištel mednje, kajti kraljeva beseda je bila Joábu gnusna.',
        7: 'Bog pa je bil razžaljen s to stvarjo, zato je udaril Izraela.',
        8: 'David je rekel Bogu: »Silno sem grešil, ker sem storil to stvar. Toda zdaj te rotim, odstrani krivičnost svojega služabnika, kajti storil sem zelo nespametno.«',
        9: 'Gospod je spregovoril Davidovemu vidcu Gadu:',
        10: '»Pojdi in povej Davidu, rekoč: ›Tako govori Gospod: ›Ponujam ti tri stvari. Izberi eno izmed njih, da ti jo bom lahko storil.‹«',
        11: 'Tako je Gad prišel k Davidu in mu rekel: »Tako govori Gospod: ›Izberi si',
        12: 'ali tri leta lakote, ali tri mesece uničenja pred svojimi sovražniki, medtem ko te dohiteva meč tvojih sovražnikov, ali tri dni Gospodovega meča, celo kužne bolezni v deželi in uničevanje od Gospodovega angela po vseh Izraelovih pokrajinah. Sedaj si torej svetuj, kakšno besedo naj ponovno prinesem tistemu, ki me je poslal.‹«',
        13: 'David je rekel Gadu: »V veliki stiski sem. Naj torej padem v Gospodovo roko, kajti zelo velika so njegova usmiljenja, toda naj ne padem v roko človeka.«',
        14: 'Tako je Gospod nad Izrael poslal kužno bolezen in izmed Izraela je padlo sedemdeset tisoč mož.',
        15: 'Bog je poslal angela k Jeruzalemu, da ga uniči. Medtem ko je ta uničeval, je Gospod opazoval, se pokesal od zla in rekel angelu, ki je uničeval: »Dovolj je, zadrži sedaj svojo roko.« In Gospodov angel je stal pri mlatišču Jebusejca Ornana.',
        16: 'David je povzdignil svoje oči in zagledal Gospodovega angela stati med zemljo in nebom, ki je imel v svoji roki izvlečen meč, iztegnjen nad Jeruzalemom. Potem so David in starešine Izraela, ki so bili oblečeni v vrečevino, padli na svoje obraze.',
        17: 'David pa je rekel Bogu: » Ali nisem to jaz, ki sem zapovedal, da se ljudstvo prešteje? Celo jaz sem ta, ki je grešil in zares storil zlo. Toda kar se tiče teh ovc, kaj so te storile? Naj bo tvoja roka, prosim te, oh Gospod, moj Bog, na meni in na hiši mojega očeta, toda ne na tvojem ljudstvu, da bi bili trpinčeni.«',
        18: 'Potem je Gospodov angel zapovedal Gadu, da reče Davidu, naj gre David gor in postavi oltar Gospodu na mlatišču Jebusejca Ornana.',
        19: 'David je na Gadovo besedo, ki jo je govoril v Gospodovem imenu, odšel gor.',
        20: 'Ornan pa se je obrnil in zagledal angela in njegovi štirje sinovi so se z njim vred skrili. Torej Ornan je mlatil pšenico.',
        21: 'Ko je David prišel k Ornanu, je Ornan pogledal in zagledal Davida in šel ven iz mlatišča in se pripognil k Davidu s svojim obrazom do tal.',
        22: 'Potem je David rekel Ornanu: »Zagotovi mi prostor tega mlatišča, da bom na njem lahko zgradil oltar Gospodu. Zagotovil mi ga boš za polno ceno, da bo nadloga lahko ustavljena pred ljudstvom.«',
        23: 'Ornan je rekel Davidu: »Vzemi to k sebi in naj moj gospod kralj stori to, kar je dobro v njegovih očeh. Glej, dam ti tudi vola za žgalne daritve, mlatilne priprave za les in pšenico za jedilno daritev; vse to dam.«',
        24: 'Kralj David je rekel Ornanu: »Ne, temveč bom to resnično kupil za polno ceno, kajti ne bom vzel tega, kar je tvoje, za Gospoda niti žgalne daritve daroval brez stroška.«',
        25: 'Tako je David dal Ornanu za prostor šeststo šeklov zlata po teži.',
        26: 'David je tam zgradil oltar Gospodu in daroval žgalne daritve in mirovne daritve in klical h Gospodu in ta mu je iz nebes odgovoril z ognjem na oltar žgalne daritve.',
        27: 'Gospod je zapovedal angelu in ta je svoj meč ponovno vtaknil v svojo nožnico.',
        28: 'V tistem času, ko je David videl, da mu je Gospod odgovoril na mlatišču Jebusejca Ornana, potem je tam žrtvoval.',
        29: 'Kajti Gospodovo šotorsko svetišče, ki ga je Mojzes naredil v divjini in oltar žgalne daritve sta bila v tem obdobju na visokem kraju pri Gibeónu.',
        30: 'Toda David ni mogel iti predenj, da bi povprašal od Boga, kajti bal se je zaradi meča Gospodovega angela.',
    },
    22: {
        1: 'Potem je David rekel: »To je hiša Gospoda Boga in to je oltar žgalne daritve za Izraela.«',
        2: 'David je zapovedal, da zberejo skupaj tujce, ki so bili v Izraelovi deželi in postavil je zidarje, da izklesajo kamne, da zgradijo Božjo hišo.',
        3: 'David je pripravil železa v obilju za žeblje za duri velikih vrat in za vezi in brona v obilju, brez teže.',
        4: 'Tudi cedrovih dreves v obilju, kajti Sidónci in tisti iz Tira so Davidu prinesli veliko cedrovega lesa.',
        5: 'David je rekel: »Moj sin Salomon je mlad in nežen, hiša, ki naj se zgradi za Gospoda, pa mora biti silno prekrasna od slovesa in od slave po vseh deželah, zato bom torej naredil priprave zanjo.« Tako je David pred svojo smrtjo [vsega] obilno pripravil.',
        6: 'Potem je dal poklicati svojega sina Salomona in ga zadolžil, da zgradi hišo za Gospoda, Izraelovega Boga.',
        7: 'David je rekel Salomonu: »Moj sin, kar se mene tiče, je bilo v mojih mislih, da zgradim hišo imenu Gospoda, svojega Boga,',
        8: 'toda k meni je prišla Gospodova beseda, rekoč: ›Obilno si prelival kri in storil velike vojne. Ne boš gradil hiše mojemu imenu, ker si v mojem pogledu na zemlji prelil mnogo krvi.',
        9: 'Glej, rojen ti bo sin, ki bo mož počitka in dal mu bom počitek pred vsemi njegovimi sovražniki naokoli, kajti njegovo ime bo Salomon in jaz bom v njegovih dneh Izraelu dal mir in spokojnost.',
        10: 'Zgradil bo hišo za moje ime in on bo moj sin in jaz bom njegov oče in jaz bom vzpostavil prestol njegovega kraljestva nad Izraelom na veke.‹',
        11: 'Sedaj moj sin, Gospod naj bo s teboj in bodi uspešen in zgradi hišo Gospoda, svojega Boga, kakor je govoril o tebi.',
        12: 'Samo Gospod naj ti da modrost in razumevanje in te zadolži glede Izraela, da se boš lahko držal postave Gospoda, svojega Boga.',
        13: 'Potem boš uspel, če paziš, da izpolnjuješ zakone in sodbe, ki jih je Gospod zapovedal Mojzesu glede Izraela. Bodi močan in odločnega poguma. Ne boj se niti ne bodi zaprepaden.',
        14: 'Torej glej, v svoji stiski sem za Gospodovo hišo pripravil sto tisoč talentov zlata in milijon talentov srebra, brona in železa pa brez teže, kajti tega je v obilju. Tudi les in kamenje sem pripravil in ti lahko k temu dodaš.',
        15: 'Poleg tega je tam s teboj delavcev v obilju, kamnosekov in obdelovalcev kamna in lesa, in vseh vrst spretnih mož za vsako vrsto dela.',
        16: 'Zlatu, srebru, bronu in železu ni števila. Vstani torej in delaj in Gospod naj bo s teboj.«',
        17: 'David je tudi vsem Izraelovim princem zapovedal, da pomagajo njegovemu sinu Salomonu, rekoč:',
        18: '» Mar ni z vami Gospod, vaš Bog? In ali vam ni dal počitka na vsaki strani? Kajti prebivalce dežele je izročil v mojo roko in dežela je podjarmljena pred Gospodom in pred njegovim ljudstvom.',
        19: 'Pripravite torej svoje srce in svojo dušo, da iščete Gospoda, svojega Boga. Vstanite torej in zgradite svetišče Gospodu Bogu, da se prinese skrinja Gospodove zaveze in svete Božje posode v hišo, ki naj bo zgrajena Gospodovemu imenu.«',
    },
    23: {
        1: 'Torej ko je bil David star in izpolnjen z dnevi, je nad Izraelom postavil svojega sina Salomona.',
        2: 'Ta je zbral skupaj vse Izraelove prince, z duhovniki in Lévijevci.',
        3: 'Torej Lévijevci so bili prešteti od starosti tridesetih let in navzgor. Njihovo število po njihovih glavah, oseb, je bilo osemintrideset tisoč.',
        4: '»Izmed katerih je bilo štiriindvajset tisoč, da vodijo delo Gospodove hiše, šest tisoč pa je bilo častnikov in sodnikov.',
        5: 'Poleg tega je bilo štiri tisoč vratarjev in štiri tisoč jih je hvalilo Gospoda z glasbili, ki sem jih naredil,« je rekel David, »da s temi hvalijo.«',
        6: 'David jih je razdelil v skupine med Lévijeve sinove, namreč Geršóna, Keháta in Meraríja.',
        7: 'Izmed Geršónovcev sta bila Ladán in Šimí.',
        8: 'Ladánovi sinovi: vodja je bil Jehiél, Zetám in Joél, trije.',
        9: 'Šimíjevi sinovi: Šelomít, Haziél in Harán, trije. To so bili vodje Ladánovih očetov.',
        10: 'Šimíjevi sinovi so bili: Jahat, Ziná, Jeúš in Berijá. Ti štirje so bili Šimíjevi sinovi.',
        11: 'Jahat je bil vodja, Zizá pa drugi, toda Jeúš in Berijá nista imela veliko sinov, zato sta bila v enem štetju, glede na hišo svojega očeta.',
        12: 'Kehátovi sinovi: Amrám, Jichár, Hebrón in Uziél, štirje.',
        13: 'Amrámova sinova: Aron in Mojzes. Aron je bil odbran, da posvečuje najsvetejše stvari, on in njegovi sinovi na veke, da zažigajo kadilo pred Gospodom, da mu služijo in da v njegovem imenu blagoslavljajo na veke.',
        14: 'Torej glede Mojzesa, Božjega moža, njegovi sinovi so bili imenovani po Lévijevemu rodu.',
        15: 'Mojzesova sinova sta bila Geršóm in Eliézer.',
        16: 'Od Geršómovih sinov je bil vodja Šebuél.',
        17: 'Eliézerjevi sinovi so bili vodja Rehabjá. Eliézer pa ni imel nobenih drugih sinov, toda Rehabjájevih sinov je bilo zelo mnogo.',
        18: 'Izmed Jichárjevih sinov: vodja Šelomít.',
        19: 'Izmed Hebrónovih sinov: prvi Jerijá, drugi Amarjá, tretji Jahaziél in četrti Jekamám.',
        20: 'Uziélova sinova: prvi Miha in drugi Jišijá.',
        21: 'Meraríjeva sinova: Mahlí in Muší. Mahlíjeva sinova: Eleazar in Kiš.',
        22: 'Eleazar pa je umrl in ni imel sinov, temveč hčere in vzeli so jih njihovi bratje, Kiševi sinovi.',
        23: 'Mušíjevi sinovi: Mahlí, Eder in Jeremót, trije.',
        24: 'To so bili Lévijevi sinovi po hiši svojih očetov, torej vodje očetov, kakor so bili prešteti po številu imen njihovih glav, ki so opravljali delo službe Gospodove hiše, od starosti dvajsetih let in navzgor.',
        25: 'Kajti David je rekel: » Gospod, Izraelov Bog, je svojemu ljudstvu dal počitek, da bi na veke lahko prebivali v Jeruzalemu,',
        26: 'in tudi Lévijevcem; ne bodo več nosili šotorskega svetišča niti nobene njegove posode za njegovo službo.«',
        27: 'Kajti po zadnjih Davidovih besedah so bili Lévijevci prešteti od dvajsetih let starosti in naprej,',
        28: 'ker je bila njihova služba, da čakajo na Aronove sinove za službo Gospodovi hiši, na dvorih in v sobah in v očiščevanju vseh svetih stvari in delu službe Božje hiše.',
        29: 'Tako za hleb navzočnosti kakor za fino moko, za jedilno daritev in za nekvašene kolače in za tisto, kar je spečeno na ponvi in za to, kar je ocvrto in za vse vrste mer in velikosti',
        30: 'in da vsako jutro stojijo, da se zahvaljujejo in hvalijo Gospoda in prav tako zvečer.',
        31: 'In da vse žgalne daritve darujejo Gospodu na šabate, na mlaje in na določene praznike, po številu, glede na ukaz, ki jim je zapovedan, nenehno pred Gospodom,',
        32: 'in da naj se držijo zadolžitve šotorskega svetišča skupnosti in zadolžitve svetega kraja in zadolžitve Aronovih sinov, svojih bratov, v službi Gospodove hiše.',
    },
    24: {
        1: 'Torej to so oddelki Aronovih sinov. Aronovi sinovi: Nadáb, Abihú, Eleazar in Itamár.',
        2: 'Toda Nadáb in Abihú sta umrla pred njunim očetom in nista imela otrok, zato sta duhovniško službo opravljala Eleazar in Itamár.',
        3: 'David jih je razdelil, tako Cadóka izmed Eleazarjevih sinov kot Ahiméleha izmed Itamárjevih sinov, glede na njihovo opravilo v njihovi službi.',
        4: 'Med Eleazarjevimi sinovi pa se je našlo več vodilnih mož kakor med Itamárjevimi sinovi; in tako so bili razdeljeni. Med Eleazarjevimi sinovi je bilo šestnajst vodilnih mož iz hiše njihovih očetov in osem med Itamárjevimi sinovi, glede na hišo njihovih očetov.',
        5: 'Tako so bili razdeljeni z žrebom, ena vrsta z drugo; za upravitelje svetišča in upravitelje Božje hiše so bili izmed Eleazarjevih sinov in izmed Itamárjevih sinov.',
        6: 'Netanélov sin Šemajá, pisar, eden izmed Lévijevcev, jih je popisal pred kraljem, princi, duhovnikom Cadókom in Abjatárjevim sinom Ahimélehom in pred vodji očetov duhovnikov in Lévijevcev. Ena glavna družina je bila vzeta za Eleazarja in ena je bila vzeta za Itamárja.',
        7: 'Torej prvi žreb je izšel za Jojaríba, drugi za Jedajája,',
        8: 'tretji za Haríma, četrti za Seoríma,',
        9: 'peti za Malkijája, šesti za Mijamína,',
        10: 'sedmi za Koca, osmi za Abíja,',
        11: 'deveti za Ješúa, deseti za Šehanjája,',
        12: 'enajsti za Eljašíba, dvanajsti za Jakíma,',
        13: 'trinajsti za Hupája, štirinajsti za Ješebába,',
        14: 'petnajsti za Bilgája, šestnajsti za Imêrja,',
        15: 'sedemnajsti za Hezírja, osemnajsti za Hapicéca,',
        16: 'devetnajsti za Petahjája, dvajseti za Jehezkéla,',
        17: 'enaindvajseti za Jahína, dvaindvajseti za Gamúla,',
        18: 'triindvajseti za Delajája, štiriindvajseti za Maazjája.',
        19: 'To so bili njihovi vrstni redi v njihovi službi, da pridejo v Gospodovo hišo, glede na njihov način, pod njihovim očetom Aronom, kakor mu je zapovedal Gospod, Izraelov Bog.',
        20: 'Preostali izmed Lévijevih sinov so bili tile: izmed Amrámovih sinov Šubaél, izmed Šubaélovih sinov Jehdejá.',
        21: 'Glede Rehabjá, izmed sinov Rehabjá je bil prvi Jišijá.',
        22: 'Izmed Jichárovcev Šelomot, izmed Šelomotovih sinov Jahat.',
        23: 'Hebrónovi sinovi: prvi Jerijá, drugi Amarjá, tretji Jahaziél in četrti Jekamám.',
        24: 'Izmed Uziélovih sinov Miha, izmed Mihovih sinov Šamír.',
        25: 'Mihov brat je bil Jišijá, izmed Jišijájevih sinov Zeharjá.',
        26: '§ Meraríjevi sinovi so bili Mahlí in Muší. Jaazijájevi sinovi: Beno.',
        27: '§ Merarijevi sinovi po Jaazijáju: Beno, Šohám, Zahúr in Ibri.',
        28: 'Iz Mahlíja je prišel Eleazar, ki ni imel sinov.',
        29: 'Glede Kiša: Kišev sin je bil Jerahmeél.',
        30: 'Tudi Mušíjevi sinovi: Mahlí, Eder in Jerimót. To so bili sinovi Lévijevcev po hiši njihovih očetov.',
        31: 'Tudi ti so metali žrebe nasproti svojih bratov, Aronovih sinov, v prisotnosti kralja Davida, Cadóka, Ahiméleha in vodje očetov duhovnikov in Lévijevcev, celo glavnim očetom nasproti njihovim mlajšim bratom.',
    },
    25: {
        1: 'Poleg tega so David in poveljniki vojske oddvojili k službi od Asáfovih, Hemánovih in Jedutúnovih sinov, ki naj bi prerokovali s harfami, s plunkami in s cimbalami. Število delavcev glede na njihovo službo je bilo:',
        2: 'izmed Asáfovih sinov Zahúr, Jožef, Netanjá in Asaréla, Asáfovi sinovi pod Asáfovo roko, ki so prerokovali glede na kraljev ukaz.',
        3: '§ Od Jedutúna: Jedutúnovi sinovi Gedaljá, Cerí, Ješajá, Hašabjá, Matitjá, šest, pod rokami njihovega očeta Jedutúna, ki so prerokovali s harfo, da se zahvaljujejo in hvalijo Gospoda.',
        4: 'Od Hemána: Hemánovi sinovi Bukijá, Matanjá, Uziél, Šebuél, Jerimót, Hananjá, Hananí, Eliát, Gidálti, Romámti Ezer, Jošbekáša, Malóti, Hotír in Mahaziót.',
        5: 'Vsi ti so bili sinovi kraljevega vidca Hemána v Božjih besedah, da dvigujejo rog. In Bog je dal Hemánu štirinajst sinov in tri hčere.',
        6: 'Vsi ti so bili pod rokami njihovega očeta za pesem v Gospodovi hiši s cimbalami, plunkami in harfami, za službo Božje hiše, glede na kraljev ukaz Asáfu, Jedutúnu in Hemánu.',
        7: 'Tako je bilo njihovo število, z njihovimi brati, ki so bili poučeni v Gospodovih pesmih, celó vseh, ki so bili spretni, dvesto oseminosemdeset.',
        8: 'Metali so žrebe, stražo do straže, tako majhen kakor velik, učitelj kakor učenec.',
        9: 'Torej prvi žreb je prišel za Asáfa k Jožefu; drugi Gedaljáju, katerih je bilo z njegovimi brati in sinovi dvanajst;',
        10: 'tretji Zahúrju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        11: 'četrti Izriju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        12: 'peti Netanjáju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        13: 'šesti Bukijáju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        14: 'sedmi Jesarelu, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        15: 'osmi Ješajáju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        16: 'deveti Matanjáju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        17: 'deseti Šimíju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        18: 'enajsti Azarélu, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        19: 'dvanajsti Hašabjáju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        20: 'trinajsti Šubaélu, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        21: 'štirinajsti Matitjáju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        22: 'petnajsti Jeremótu, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        23: 'šestnajsti Hananjáju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        24: 'sedemnajsti Jošbekášaju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        25: 'osemnajsti Hananíju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        26: 'devetnajsti Malótiju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        27: 'dvajseti Eliátaju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        28: 'enaindvajseti Hotírju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        29: 'dvaindvajseti Gidáltiju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        30: 'triindvajseti Mahaziótaju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst;',
        31: 'štiriindvajseti Romámti Ezerju, njemu, njegovim sinovom in njegovim bratom, bilo jih je dvanajst.',
    },
    26: {
        1: 'Glede na oddelke vratarjev je bil od Kórahovcev Mešelemjá, sin Koréja izmed Asáfovih sinov.',
        2: 'Mešelemjájevi sinovi so bili prvorojenec Zeharjá, drugi Jediaél, tretji Zebadjá, četrti Jatniél,',
        3: 'peti Elám, šesti Johanán, sedmi Eljoenáj.',
        4: 'Poleg tega so bili Obéd Edómovi sinovi prvorojenec Šemajá, drugi Jozabád, tretji Joáh, četrti Sahár, peti Netanél,',
        5: 'šesti Amiél, sedmi Isahár in osmi Peuletáj, kajti Bog ga je blagoslovil.',
        6: 'Tudi njegovemu sinu Šemajáju so bili rojeni sinovi, ki so vladali po hiši svojih očetov, kajti bili so močni junaški možje.',
        7: 'Šemajájevi sinovi: Otní, Refaél, Obéd, Elzabád, katerega bratje so bili močni možje, Elihú in Semahjá.',
        8: 'Vseh teh izmed Obéd Edómovih sinov in njihovih bratov, sposobnih mož za službo je bilo dvainšestdeset.',
        9: 'Mešelemjá je imel sinove in brate, močne može, osemnajst.',
        10: 'Tudi Hosá, izmed Meraríjevih otrok, je imel sinove: vodja Šimrí, (kajti čeprav ni bil prvorojenec, ga je vendar njegov oče naredil za vodjo)',
        11: 'drugi Hilkijá, tretji Tebaljá, četrti Zeharjá. Vseh sinov Hosájevih bratov je bilo trinajst.',
        12: 'Med temi so bili oddelki vratarjev, celó med vodilnimi možmi so imeli straže, da služijo eden nasproti drugemu v Gospodovi hiši.',
        13: 'Metali so žrebe, tako majhni kakor veliki, glede na hišo njihovih očetov, za vsaka velika vrata.',
        14: 'Žreb proti vzhodu je zadel Šelemjája. Potem so metali žrebe za Zeharjá, njegovega sina, modrega svetovalca in njegov žreb je izšel proti severu.',
        15: 'Za Obéd Edóma in za njegove sinove od Asupimove hiše proti jugu.',
        16: 'Šupímu in Hosáju je žreb izšel proti zahodu z velikimi vrati Šaléheta, pri tlakovani pešpoti vzpona, straža proti straži.',
        17: 'Proti vzhodu je bilo šest Lévijevcev, štirje na dan proti severu, štirje na dan proti jugu in proti Asupimu dva in dva.',
        18: '§ Pri Parbarju proti zahodu, štirje pri tlakovani pešpoti in dva pri Parbarju.',
        19: 'To so oddelki vratarjev med Koréjevimi sinovi in med Meraríjevimi sinovi.',
        20: 'Izmed Lévijevcev je bil Ahíja nad zakladnicami Božje hiše in nad zakladnicami posvečenih stvari.',
        21: 'Glede Ladánovih sinov: sinovi Geršónca Ladána, poglavarji očetov, celó od Geršónca Ladána, je bil Jehielí.',
        22: 'Jehielíjeva sinova: Zetám in njegov brat Joél, ki sta bila nad zakladnicami Gospodove hiše.',
        23: 'Izmed Amrámovcev, Jichárovcev, Hebróncev in Uziélovcev',
        24: 'je bil Šebuél, Geršómov sin, Mojzesov sin, vladar nad zakladnicami.',
        25: 'Njegovi bratje po Eliézerju: njegov sin Rehabjá, njegov sin Ješajá, njegov sin Jorám, njegov sin Zihrí in njegov sin Šelomít.',
        26: 'Ta Šelomít in njegovi bratje so bili nad vsemi zakladnicami posvečenih stvari, ki so jih kralj David, vodje očetov, tisočniki, stotniki in poveljniki vojske posvetili.',
        27: 'Od plenov, dobljenih v bitkah, so jih posvetili za vzdrževanje Gospodove hiše.',
        28: 'In vse, kar so videc Samuel, Kišev sin Savel, Nerov sin Abnêr in Cerújin sin Joáb posvetili in kdorkoli je posvetil katerokoli stvar, so bile te pod roko Šelomíta in njegovih bratov.',
        29: 'Izmed Jichárovcev so bili Kenanjá in njegovi sinovi za zunanja opravila nad Izraelom, za častnike in sodnike.',
        30: 'In izmed Hebróncev Hašabjá in njegovi bratje, junaški možje, tisoč sedemsto, so bili častniki med tistimi iz Izraela na tej strani Jordana proti zahodu v vseh Gospodovih opravilih in v kraljevi službi.',
        31: 'Med Hebrónovci je bil vodja Jerijá, torej med Hebrónovci glede na rodove svojih očetov. V štiridesetem letu Davidovega kraljevanja so jih iskali in med njimi so našli močne junaške može pri Jazêr Gileádu.',
        32: 'Njegovih bratov, junaških mož, je bilo dva tisoč in sedemsto vodij očetov, ki jih je David postavil [za] vladarje nad Rubenovci, Gádovci in polovico Manásejevega rodu, za vsako zadevo glede Boga in kraljevih zadev.',
    },
    27: {
        1: 'Torej Izraelovi otroci po njihovem številu, namreč vodja očetov poveljnikov nad tisočimi in nad stotimi in njihovi častniki, ki so služili kralju v vsaki zadevi oddelkov, ki so prihajali in odhajali mesec za mesecem, vse mesece leta; od vsakega oddelka jih je bilo štiriindvajset tisoč.',
        2: 'Nad prvo skupino za prvi mesec je bil Zabdiélov sin Jašobám in v njegovi skupini jih je bilo štiriindvajset tisoč.',
        3: 'Izmed Perecovih otrok je bil vodja vseh poveljnikov vojske za prvi mesec.',
        4: 'Nad skupino drugega meseca je bil Ahóahovec Dodáj in iz njegove skupine je bil tudi vladar Miklót. Tudi v njegovi skupini jih je bilo štiriindvajset tisoč.',
        5: 'Tretji poveljnik vojske za tretji mesec je bil Benajá, sin Jojadája, vélikega duhovnika in v njegovi skupini jih je bilo štiriindvajset tisoč.',
        6: 'To je ta Benajá, ki je bil mogočen med tridesetimi in nad tridesetimi. V njegovi skupini je bil njegov sin Amizabád.',
        7: 'Četrti poveljnik za četrti mesec je bil Joábov brat Asaél in za njim njegov sin Zebadjá. V njegovi skupini jih je bilo štiriindvajset tisoč.',
        8: 'Peti poveljnik za peti mesec je bil Zêrahovec Šamhút. V njegovi skupini jih je bilo štiriindvajset tisoč.',
        9: 'Šesti poveljnik za šesti mesec je bil Irá, sin Tekójčana Ikéša. V njegovi skupini jih je bilo štiriindvajset tisoč.',
        10: 'Sedmi poveljnik za sedmi mesec je bil Péletovec Helec, izmed Efrájimovih otrok. V njegovi skupini jih je bilo štiriindvajset tisoč.',
        11: 'Osmi poveljnik za osmi mesec je bil Hušán Sibeháj izmed Zerahovcev. V njegovi skupini jih je bilo štiriindvajset tisoč.',
        12: 'Deveti poveljnik za deveti mesec je bil Abiézer Anatotčan izmed Benjaminovcev. V njegovi skupini jih je bilo štiriindvajset tisoč.',
        13: 'Deseti poveljnik za deseti mesec je bil Netófčan Mahráj izmed Zerahovcev. V njegovi skupini jih je bilo štiriindvajset tisoč.',
        14: 'Enajsti poveljnik za enajsti mesec je bil Piratónec Benajá izmed Efrájimovih otrok. V njegovi skupini jih je bilo štiriindvajset tisoč.',
        15: 'Dvanajsti poveljnik za dvanajsti mesec je bil Netófčan Heldáj iz Otniéla. V njegovi skupini jih je bilo štiriindvajset tisoč.',
        16: 'Nadalje je bil nad Izraelovimi rodovi vladar Rubenovcev Zihríjev sin Eliézer; izmed Simeoncev Maahájev sin Šefatjá;',
        17: 'izmed Lévijevcev Kemuélov sin Hašabjá; izmed Aroncev Cadók;',
        18: 'izmed Judovcev Elihú, eden izmed Davidovih bratov; izmed Isahárjevcev Mihaelov sin Omri;',
        19: 'izmed Zábulonovcev Obadjájev sin Jišmajá; izmed Neftálijevcev Azriélov sin Jerimót;',
        20: 'izmed Efrájimovih otrok Azazjájev sin Hošéa; izmed polovice Manásejevega rodu Pedajájev sin Joél;',
        21: 'izmed polovice Manásejevega rodu v Gileádu Zaharijev sin Idó; izmed Benjaminovcev Abnêrjev sin Jaasiél;',
        22: 'izmed Danovcev Jerohámov sin Azarél. Ti so bili princi Izraelovih rodov.',
        23: 'Toda David ni preštel tistih, ki so bili stari dvajset let in mlajših, ker je Gospod rekel, da bo on pomnožil Izraela kakor zvezd neba.',
        24: 'Cerújin sin Joáb je začel šteti, toda ni končal, ker je zaradi tega padel bes zoper Izraela. Niti število ni bilo vpisano v poročilo kronik kralja Davida.',
        25: 'Nad kraljevimi zakladnicami je bil Adiélov sin Azmávet. Nad skladišči, na poljih, v mestih, vaseh in gradovih je bil Uzíjahov sin Jehonatan.',
        26: 'Nad tistimi, ki so opravljali poljsko delo obdelovanja zemlje, je bil Kelúbov sin Ezrí.',
        27: 'Nad vinogradi je bil Ramatejec Šimí. Nad donosom vinogradov za vinske kleti je bil Šefámec Zabdí.',
        28: 'Nad oljkami in egiptovskimi smokvami, ki so bile na nizkih ravnicah, je bil Géderčan Báal Hanán. Nad shrambami olja je bil Joáš.',
        29: 'Nad čredami, ki so se pasle v Šarónu, je bil Šarónec Šitráj. Nad čredami, ki so bile v dolinah, je bil Adlájev sin Šafát.',
        30: 'Nad kamelami je bil tudi Izmaelec Obíl. Nad osli je bil Meronočán Jehdejá.',
        31: 'Nad tropi je bil Hagríjevec Jazíz. Vsi ti so bili vladarji imetja, ki je bilo od kralja Davida.',
        32: 'Tudi Davidov stric Jonatan je bil svetovalec, moder mož in pisar. In Hahmoníjev sin Jehiél je bil s kraljevimi sinovi.',
        33: 'Ahitófel je bil kraljev svetovalec in Arkéjec Hušáj je bil kraljev družabnik.',
        34: 'Za Ahitófelom sta bila Benajájev sin Jojadá in Abjatár. General kraljeve vojske pa je bil Joáb.',
    },
    28: {
        1: 'David je zbral vse Izraelove prince, prince rodov in poveljnike skupin, ki so služili kralju po skupini in poveljnike nad tisočimi, poveljnike nad stotimi in oskrbnike nad vsem imetjem in posestjo kralja in njegovih sinov, s častniki in z mogočnimi možmi in z vsemi hrabrimi možmi v Jeruzalem.',
        2: 'Potem je kralj David stopil na svoja stopala in rekel: »Poslušajte me, moji bratje in moje ljudstvo: › Kar se mene tiče, sem imel v svojem srcu, da zgradim hišo počitka za skrinjo Gospodove zaveze in za pručko našega Boga in sem pripravil za gradnjo,',
        3: 'toda Bog mi je rekel: ›Ne boš gradil hiše mojemu imenu, ker si bil bojevnik in si prelival kri.‹',
        4: 'Vendar je Gospod, Izraelov Bog, mene izbral pred vso hišo mojega očeta, da bi bil na veke kralj nad Izraelom, kajti Juda je izbral, da bi bil vladar; in od Judove hiše, hišo mojega očeta; in med sinovi mojega očeta sem mu bil všeč, da me je postavil za kralja nad vsem Izraelom,',
        5: 'in izmed vseh mojih sinov (kajti Gospod mi je dal mnogo sinov), je izbral mojega sina Salomona, da sedi na prestolu Gospodovega kraljestva nad Izraelom.',
        6: 'Rekel mi je: ›Tvoj sin Salomon bo zgradil mojo hišo in moje dvore, kajti izbral sem ga, da bo moj sin in jaz bom njegov oče.',
        7: 'Poleg tega bom na veke utrdil njegovo kraljestvo, če bo stalno izpolnjeval moje zapovedi in moje sodbe, kakor ta dan.‹',
        8: 'Zdaj se torej pred očmi vsega Izraela, Gospodove skupnosti in v občinstvu našega Boga, držite in iščite vse zapovedi Gospoda, svojega Boga, da boste lahko posedli to dobro deželo in jo pustili za dediščino svojim otrokom za seboj na veke.',
        9: 'Ti pa, moj sin Salomon, spoznaj Boga svojega očeta in mu služi s popolnim srcem in z voljnim umom, kajti Gospod preiskuje vsa srca in razume vse miselne zamisli. Če ga boš iskal, ga boš našel, toda če ga zapustiš, te bo on zavrgel na veke.',
        10: 'Pazi torej, kajti Gospod te je izbral, da zgradiš hišo za svetišče. Bodi močan in to stôri.‹«',
        11: 'Potem je David svojemu sinu Salomonu dal vzorec preddverja, njegovih hiš, njegovih zakladnic, njegovih gornjih sob, njegovih notranjih dvoran in kraja sedeža milosti,',
        12: 'vzorec vsega, kar je imel po duhu glede dvorov Gospodove hiše in vseh sob naokoli, zakladnic Božje hiše in zakladnic posvečenih stvari.',
        13: 'Tudi za skupine duhovnikov in Lévijevcev in za vse delo službe Gospodove hiše in za vse posode službe v Gospodovi hiši.',
        14: 'Dal je zlata po teži za stvari iz zlata, za vse priprave vseh vrst službe; tudi srebra za vse priprave iz srebra po teži, za vse priprave vsake vrste službe.',
        15: 'Celo težo za svečnike iz zlata in za njihove svetilke iz zlata po teži za vsak svečnik in za njihove svetilke. In za svečnike iz srebra po teži, tako za svečnik in tudi za njihove svetilke, glede na uporabo vsakega svečnika.',
        16: 'Po teži je dal zlata za mize hlebov navzočnosti za vsako mizo in podobno zlata za mize iz srebra.',
        17: 'Tudi čistega zlata za kavlje za meso, skledice in čaše. Za zlate umivalnike je dal zlata po teži za vsak umivalnik; in podobno srebra, po teži za vsak umivalnik iz srebra;',
        18: 'Za kadilni oltar prečiščeno zlato po teži in zlata za vzorec bojnega voza kerubov, ki razprostirata svoje peruti in pokrivata skrinjo Gospodove zaveze.',
        19: '»Vse to,« je rekel David, »mi je Gospod dal razumeti v pisanju po svoji roki nad menoj, torej vsa dela tega vzorca.«',
        20: 'David je rekel svojemu sinu Salomonu: »Bodi močan in odločnega poguma in stôri to. Ne boj se niti ne bodi zaprepaden, kajti Gospod Bog, celó moj Bog, bo s teboj. Ne bo te razočaral niti te ne bo zapustil, dokler ne dokončaš vsega dela za službo Gospodove hiše.',
        21: 'Glej, skupine duhovnikov in Lévijevcev, celo oni bodo s teboj za vso službo Božje hiše, in tam bo s teboj za vse vrste rokodelstva vsak voljan vešč mož, za vse vrste del. Tudi princi in vse ljudstvo bo popolno ob tvoji zapovedi.«',
    },
    29: {
        1: 'Nadalje je kralj David vsej skupnosti rekel: »Moj sin Salomon, ki ga je izbral sam Bog, je še mlad in nežen, delo pa je veliko, kajti palača ni za človeka, temveč za Gospoda Boga.',
        2: 'Sedaj sem z vso svojo močjo pripravil za hišo svojega Boga zlata za stvari, narejene iz zlata, srebra za stvari iz srebra, brona za stvari iz brona, železa za stvari iz železa, lesa za stvari iz lesa, oniksove kamne in kamne za vdelavo, lesketajoče kamne iz različnih barv in vse vrste dragocenih kamnov in marmornih kamnov v obilju.',
        3: 'Povrh vsega, ker sem svojo naklonjenost naravnal k hiši svojega Boga, sem dal od svojih lastnih dobrin, od zlata in srebra, ki sem ga dal k hiši svojega Boga, poleg vsega, kar sem pripravil za sveto hišo;',
        4: 'celó tri tisoč talentov zlata, od zlata iz Ofírja in sedem tisoč talentov prečiščenega srebra, da se z njim prekrije stene hiš.',
        5: 'Zlata za stvari iz zlata, srebra za stvari iz srebra in za vsako vrsto dela storjenega z rokodelčevimi rokami. In kdo bo potem ta dan voljan uméstiti svojo službo Gospodu?«',
        6: 'Potem so vodje očetov in princev iz Izraelovega rodu in poveljniki nad tisočimi in nad stotimi, z voditelji kraljevega dela, prostovoljno darovali',
        7: 'in dali za službo Božje hiše od zlata pet tisoč talentov in deset tisoč darejkov, od srebra deset tisoč talentov, od brona osemnajst tisoč talentov in sto tisoč talentov železa.',
        8: 'Tisti, pri katerih so bili najdeni dragoceni kamni, so jih dali v zakladnico Gospodove hiše po roki Geršónca Jehiéla.',
        9: 'Potem se je ljudstvo veselilo, za to, kar so voljno darovali, ker so s popolnim srcem voljno darovali Gospodu. Tudi kralj David se je veselil z veliko radostjo.',
        10: 'Zato je David blagoslovil Gospoda pred vso skupnostjo in David je rekel: »Blagoslovljen bodi ti, Gospod, Bog Izraela, našega očeta, na veke vekov.',
        11: 'Tvoja, oh Gospod, je veličina, oblast, slava, zmaga in veličastvo, kajti vse, kar je v nebesih in na zemlji, je tvoje. Tvoje je kraljestvo, oh Gospod in ti si kakor glava povišan nad vse.',
        12: 'Bogastvo in čast, oboje prihaja od tebe in ti kraljuješ nad vsem in v tvoji roki je oblast in moč in v tvoji roki je to, da narediš veliko in da daš moč vsem.',
        13: 'Zdaj torej, naš Bog, se ti zahvaljujemo in hvalimo tvoje veličastno ime.',
        14: 'Toda kdo sem jaz in kaj je moje ljudstvo, da bi bili zmožni darovati tako voljno na takšen način? Kajti vse stvari prihajajo od tebe in od tvojega lastnega smo dali tebi.',
        15: 'Kajti mi smo tujci pred teboj in začasni prebivalci, kakor so bili vsi naši očetje. Naši dnevi na zemlji so kakor senca in nobenega ni, ki bi ostal.',
        16: 'Oh Gospod, naš Bog, vsa ta zaloga, ki smo jo pripravili, da ti zgradimo hišo za tvoje sveto ime, prihaja iz tvoje roke in vse je tvoje.',
        17: 'Tudi jaz vem, moj Bog, da ti preizkušaš srce in imaš veselje v iskrenosti. Kar se mene tiče, sem v iskrenosti svojega srca voljno daroval vse te stvari in sedaj sem z radostjo videl tvoje ljudstvo, ki je tukaj prisotno, da ti voljno daruje.',
        18: 'Oh Gospod, Bog Abrahama, Izaka in Izraela, naših očetov, varuj to na veke v zamisli misli srca svojega ljudstva in si pripravi njihovo srce.',
        19: 'Mojemu sinu Salomonu daj popolno srce, da varuje tvoje zapovedi, tvoja pričevanja in tvoje zakone in da stori vse te stvari in da zgradi palačo, za katero sem naredil preskrbo.«',
        20: 'David je vsej skupnosti rekel: »Sedaj blagoslovite Gospoda, svojega Boga.« In vsa skupnost je blagoslovila Gospoda, Boga svojih očetov, sklonila svoje glave in oboževala Gospoda in kralja.',
        21: 'Žrtvovali so klavne daritve Gospodu in darovali so žgalne daritve Gospodu naslednji dan po tem dnevu, celó tisoč bikcev, tisoč ovnov in tisoč jagnjet, z njihovimi pitnimi daritvami in v obilju klavnih daritev za ves Izrael.',
        22: 'Z velikim veseljem so na ta dan jedli in pili pred Gospodom. Kralja Salomona, Davidovega sina, so drugič postavili za kralja, ga mazilili Gospodu za glavnega voditelja, Cadóka pa za duhovnika.',
        23: 'Potem se je Salomon usedel na Gospodov prestol kakor kralj namesto svojega očeta Davida in uspeval in ves Izrael ga je ubogal.',
        24: 'Vsi princi in mogočni možje in tudi vsi sinovi kralja Davida so se podredili kralju Salomonu.',
        25: 'Gospod je silno poveličal Salomona v očeh vsega Izraela in mu podelil takšno kraljevo veličastvo, kakršno ni bilo v Izraelu na nobenem kralju pred njim.',
        26: 'Tako je Jesejev sin David kraljeval nad vsem Izraelom.',
        27: 'Časa, ko je kraljeval nad Izraelom, je bilo štirideset let. Sedem let je kraljeval v Hebrónu, triintrideset let pa je kraljeval v Jeruzalemu.',
        28: 'Umrl je v dobri visoki starosti, izpolnjen z dnevi, bogastvi in častjo. Namesto njega je zakraljeval njegov sin Salomon.',
        29: 'Torej dejanja kralja Davida, prva in zadnja, glej, ta so zapisana v knjigi vidca Samuela, v knjigi preroka Natána in v knjigi vidca Gada,',
        30: 'z vsem njegovim vladanjem in njegovo močjo in časi, ki so prešli nad njim in nad Izraelom in nad vsemi kraljestvi dežel.',
    },
}
